class Solution {
 public:
  ListNode* addTwoNumbers(ListNode* l1, ListNode* l2) {
    ListNode* dummy = new ListNode();
    ListNode* res = dummy;
    int total = 0, carry = 0;

    while (l1 || l2 || carry) {
      total = carry;

      if (l1) {
        total += l1->val;
        l1 = l1->next;
      }
      if (l2) {
        total += l2->val;
        l2 = l2->next;
      }

      int num = total % 10;
      carry = total / 10;
      dummy->next = new ListNode(num);
      dummy = dummy->next;
    }

    ListNode* result = res->next;
    delete res;
    return result;
  }
};

class Solution {
 public:
  int lengthOfLongestSubstring(string s) {
    unordered_map<char, int> mp;
    int n = s.size();
    int l = 0, r = 0;
    int ans = 0;
    while (r < n) {
      while (mp[s[r]] > 0) {
        mp[s[l]]--;
        l++;
      }
      mp[s[r]]++;
      r++;
      ans = max(ans, r - l);
    }
    return ans;
  }
};

class Solution {
 public:
  double findMedianSortedArrays(vector<int>& nums1, vector<int>& nums2) {
    if (nums1.size() > nums2.size()) {
      return findMedianSortedArrays(nums2, nums1);
    }

    int len1 = nums1.size(), len2 = nums2.size();
    int left = 0, right = len1;

    while (left <= right) {
      int part1 = (left + right) / 2;
      int part2 = (len1 + len2 + 1) / 2 - part1;

      int maxLeft1 = (part1 == 0) ? INT_MIN : nums1[part1 - 1];
      int minRight1 = (part1 == len1) ? INT_MAX : nums1[part1];
      int maxLeft2 = (part2 == 0) ? INT_MIN : nums2[part2 - 1];
      int minRight2 = (part2 == len2) ? INT_MAX : nums2[part2];

      if (maxLeft1 <= minRight2 && maxLeft2 <= minRight1) {
        if ((len1 + len2) % 2 == 0) {
          return (max(maxLeft1, maxLeft2) + min(minRight1, minRight2)) / 2.0;
        } else {
          return max(maxLeft1, maxLeft2);
        }
      } else if (maxLeft1 > minRight2) {
        right = part1 - 1;
      } else {
        left = part1 + 1;
      }
    }

    return 0.0;
  }
};

class Solution {
 public:
  string longestPalindrome(string s) {
    int n = s.size();
    bool dp[1000][1000];
    string ans = "";
    int start = 0, len = 0;
    for (int i = n - 1; i >= 0; i--) {
      for (int j = i; j < n; j++) {
        if (s[i] == s[j]) {
          if (j - i <= 1) {
            dp[i][j] = true;
          } else
            dp[i][j] = dp[i + 1][j - 1];
        } else {
          dp[i][j] = false;
        }
        if (dp[i][j] && len < j - i + 1) {
          start = i;
          len = j - i + 1;
        }
      }
    }
    return s.substr(start, len);
  }
};

