    if (needle.empty()) return 0;

    int n = haystack.size();
    int m = needle.size();

    for (int i = 0; i <= n - m; i++) {
      int j = 0;

      while (j < m && haystack[i + j] == needle[j]) {
        j++;
      }

      if (j == m) {
        return i;
      }
    }

    return -1;
  }
};

class Solution {
 public:
  void nextPermutation(vector<int>& nums) {
    int n = nums.size();
    int pivot = -1;
    for (int i = n - 2; i >= 0; i--) {
      if (nums[i] < nums[i + 1]) {
        pivot = i;
        break;
      }
    }
    if (pivot == -1) {
      reverse(nums.begin(), nums.end());
      return;
    }
    for (int i = n - 1; i >= pivot; i--) {
      if (nums[i] > nums[pivot]) {
        swap(nums[i], nums[pivot]);
        break;
      }
    }
    reverse(nums.begin() + pivot + 1, nums.end());
  }
};

class Solution {
 public:
  int longestValidParentheses(string s) {
    int left = 0, right = 0, maxAns = 0;
    int n = s.size();
    for (int i = 0; i < n; i++) {
      if (s[i] == '(') {
        left++;
      } else {
        right++;
      }
      if (left == right) {
        maxAns = max(maxAns, left + right);
      } else if (right > left) {
        left = 0, right = 0;
      }
    }
    left = 0, right = 0;
    for (int i = n - 1; i >= 0; i--) {
      if (s[i] == '(') {
        left++;
      } else {
        right++;
      }
      if (left == right) {
        maxAns = max(maxAns, left + right);
      } else if (right < left) {
        left = 0, right = 0;
      }
    }
    return maxAns;
  }
};

class Solution {
 public:
  int search(vector<int>& nums, int target) {
    int st = 0, end = nums.size() - 1, mid;
    while (end - st > 1) {
      mid = (st + end) / 2;
      if (nums[mid] == target) return mid;
      // left sorted
      if (nums[mid - 1] >= nums[st]) {
        if (target >= nums[st] && target <= nums[mid - 1]) {
          end = mid - 1;
        } else {
          st = mid + 1;
        }
      }
      // right sorted
      else {
        if (nums[mid + 1] <= target && target <= nums[end]) {
          st = mid + 1;
        } else {
          end = mid - 1;
        }
      }
    }
    if (nums[end] == target)
      return end;
    else if (nums[st] == target)
      return st;
    else
      return -1;
  }
};

class Solution {
 public:
  int searchInsert(vector<int>& nums, int target) {
    int start = 0;
    int end = nums.size() - 1;
    int mid = 0;

    while (start <= end) {
      mid = start + (end - start) / 2;

      if (nums[mid] == target) {
        return mid;
      }

      else if (nums[mid] < target) {
        start = mid + 1;
      }

      else {
        end = mid - 1;
      }
    }
    return (target > nums[mid]) ? mid + 1 : mid;
  }
};

class Solution {
  bool isValid(vector<vector<char>>& board, int row, int col, char d) {
    for (int i = 0; i < 9; i++) {
      if (board[i][col] == d) {
        return false;
      }
      if (board[row][i] == d) {
        return false;
      }
    }
    int startI = row / 3 * 3;
    int startJ = col / 3 * 3;
    for (int i = 0; i < 3; i++) {
      for (int j = 0; j < 3; j++) {
        if (board[startI + i][startJ + j] == d) {
          return false;
        }
      }
    }
    return true;
  }
  bool solve(vector<vector<char>>& board) {
    for (int i = 0; i < 9; i++) {
      for (int j = 0; j < 9; j++) {
        if (board[i][j] == '.') {
          for (char d = '1'; d <= '9'; d++) {
            if (isValid(board, i, j, d)) {
              board[i][j] = d;
              if (solve(board)) {
                return true;
              }
              board[i][j] = '.';
            }
          }
          return false;
        }
      }
    }
    return true;
  }

 public:
  void solveSudoku(vector<vector<char>>& board) { solve(board); }
};

