class Solution {
  vector<vector<int>> ans;
  void solve(int idx, int& target, vector<int>& path, vector<int>& candidates) {
    int n = candidates.size();
    if (idx == candidates.size() || target < 0) {
      return;
    }
    if (target == 0) {
      ans.push_back(path);
      return;
    }
    for (int i = idx; i < n; i++) {
      target -= candidates[i];
      path.push_back(candidates[i]);
      solve(i, target, path, candidates);
      target += candidates[i];
      path.pop_back();
    }
  }

 public:
  vector<vector<int>> combinationSum(vector<int>& candidates, int target) {
    vector<int> path;
    solve(0, target, path, candidates);
    return ans;
  }
};

class Solution {
  vector<vector<int>> ans;
  void solve(int idx, int& target, vector<int>& path, vector<int>& candidates) {
    int n = candidates.size();

    if (target == 0) {
      ans.push_back(path);
      return;
    }

    for (int i = idx; i < n; i++) {
      if (candidates[i] > target) break;
      if (i > idx && candidates[i] == candidates[i - 1]) continue;
      target -= candidates[i];
      path.push_back(candidates[i]);
      solve(i + 1, target, path, candidates);
      target += candidates[i];
      path.pop_back();
    }
  }

 public:
  vector<vector<int>> combinationSum2(vector<int>& candidates, int target) {
    sort(candidates.begin(), candidates.end());
    vector<int> path;
    solve(0, target, path, candidates);
    return ans;
  }
};

class Solution {
  vector<int> nums;
  int n;
  vector<int> maxLeft() {
    vector<int> ans(n);
    ans[0] = nums[0];
    for (int i = 1; i < n; i++) {
      ans[i] = max(ans[i - 1], nums[i]);
    }
    return ans;
  }
  vector<int> maxRight() {
    vector<int> ans(n);
    ans[n - 1] = nums[n - 1];
    for (int i = n - 2; i >= 0; i--) {
      ans[i] = max(ans[i + 1], nums[i]);
    }
    return ans;
  }

 public:
  int trap(vector<int>& height) {
    nums = height;
    n = nums.size();
    vector<int> left = maxLeft();
    vector<int> right = maxRight();
    int ans = 0;
    for (int i = 0; i < n; i++) {
      ans += min(right[i], left[i]) - nums[i];
    }
    return ans;
  }
};

class Solution {
  string s, p;
  int n, m;
  vector<vector<int>> dp;
  bool rec(int i, int j) {
    if (i == s.size() && j == p.size()) {
      return true;
    }
    if (i == s.size() + 1 || j == p.size() + 1) {
      return false;
    }
    if (dp[i][j] != -1) {
      return dp[i][j];
    }
    bool ans = false;
    if (s[i] == p[j] || p[j] == '?') {
      ans |= rec(i + 1, j + 1);
    }
    if (p[j] == '*') {
      ans |= rec(i, j + 1) || rec(i + 1, j);
    }
    return dp[i][j] = ans;
  }

 public:
  bool isMatch(string s, string p) {
    this->s = s;
    this->p = p;
    n = s.size();
    m = p.size();
    dp.assign(n + 2, vector<int>(m + 2, -1));
    return rec(0, 0);
  }
};

