/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
 public:
  ListNode* rotateRight(ListNode* head, int k) {
    if (!head || !head->next || k == 0) return head;
    int L = 1;
    ListNode* tail = head;

    while (tail->next != NULL) {
      tail = tail->next;
      L++;
    }
    k = k % L;
    if (k == 0) {
      return head;
    }
    tail->next = head;
    int remain = L - k;
    ListNode* newTail = head;
    for (int c = 1; c < remain; c++) {
      newTail = newTail->next;
    }
    ListNode* newhead = newTail->next;
    newTail->next = NULL;

    return newhead;
  }
};

class Solution {
  vector<vector<int>> dp;
  int rec(int i, int j, int m, int n) {
    if (i < 0 || i > m || j < 0 || j > n) {
      return 0;
    }
    if (i == 0 && j == 0) {
      return 1;
    }
    if (dp[i][j] != -1) {
      return dp[i][j];
    }
    return dp[i][j] = rec(i - 1, j, m, n) + rec(i, j - 1, m, n);
  }

 public:
  int uniquePaths(int m, int n) {
    dp.assign(m, vector<int>(n, -1));
    return rec(m - 1, n - 1, m, n);
  }
};

class Solution {
  vector<vector<int>> dp;
  vector<vector<int>> grid;
  int n, m;
  int dfs(int i, int j) {
    if (i == n - 1 && j == m - 1) return 1;
    if (i >= n || j >= m) return 0;
    if (dp[i][j] != -1) return dp[i][j];
    if (grid[i][j]) return 0;
    int ni = i + 1, nj = j + 1;
    int ans = 0;
    if (ni < n) {
      ans += dfs(ni, j);
    }
    if (nj < m) {
      ans += dfs(i, nj);
    }
    return dp[i][j] = ans;
  }

 public:
  int uniquePathsWithObstacles(vector<vector<int>>& obstacleGrid) {
    grid = obstacleGrid;
    n = grid.size(), m = grid[0].size();
    if (grid[n - 1][m - 1]) return 0;
    dp.assign(n, vector<int>(m, -1));
    return dfs(0, 0);
  }
};

class Solution {
  int rec(vector<vector<int>>& grid, int i, int j, vector<vector<int>>& dp) {
    int n = grid.size();
    int m = grid[0].size();
    if (i == n - 1 && j == m - 1) {
      return dp[i][j] = grid[i][j];
    }
    if (i == n || j == m) {
      return 1e9;
    }
    if (dp[i][j] != -1) {
      return dp[i][j];
    }
    int down = grid[i][j] + rec(grid, i + 1, j, dp);
    int right = grid[i][j] + rec(grid, i, j + 1, dp);
    return dp[i][j] = min(down, right);
  }

 public:
  int minPathSum(vector<vector<int>>& grid) {
    int n = grid.size();
    int m = grid[0].size();
    vector<vector<int>> dp(n + 1, vector<int>(m + 1, -1));
    return rec(grid, 0, 0, dp);
  }
};

