class Solution {
 public:
  string addBinary(string a, string b) {
    string res = "";
    int i = a.size() - 1, j = b.size() - 1, carry = 0;

    while (i >= 0 || j >= 0 || carry) {
      int sum = carry;
      if (i >= 0) sum += a[i--] - '0';
      if (j >= 0) sum += b[j--] - '0';
      res += (sum % 2) + '0';
      carry = sum / 2;
    }
    reverse(res.begin(), res.end());
    return res;
  }
};

class Solution {
 public:
  int mySqrt(int x) {
    if (x < 2) return x;

    int left = 1, right = x / 2;

    while (left <= right) {
      int mid = left + (right - left) / 2;
      long long square = (long long)mid * mid;

      if (square == x) {
        return mid;
      } else if (square < x) {
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }

    return right;
  }
};

