class Solution {
 public:
  bool search(vector<int>& nums, int t) {
    int n = nums.size();
    int st = 0, end = n - 1, mid;
    while (st <= end) {
      mid = st + (end - st) / 2;
      if (nums[mid] == t) return 1;
      if (nums[st] == nums[mid] && nums[mid] == nums[end]) {
        st++, end--;
        continue;
      }
      if (nums[st] <= nums[mid]) {
        if (nums[mid] > t && nums[st] <= t) {
          end = mid - 1;
        } else {
          st = mid + 1;
        }
      } else {
        if (nums[mid] < t && t <= nums[end]) {
          st = mid + 1;
        } else {
          end = mid - 1;
        }
      }
    }
    return 0;
  }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
 public:
  ListNode* deleteDuplicates(ListNode* head) {
    set<int> st;
    if (head == NULL) {
      return NULL;
    }
    ListNode* curr = head;
    st.insert(curr->val);
    while (curr->next != NULL) {
      if (st.count(curr->next->val)) {
        curr->next = curr->next->next;
      } else {
        st.insert(curr->next->val);
        curr = curr->next;
      }
    }
    return head;
  }
};

class Solution {
  vector<int> nsef(vector<int>& heights) {
    int n = heights.size();
    vector<int> ans(n);
    stack<int> st;
    for (int i = n - 1; i >= 0; i--) {
      while (!st.empty() && heights[st.top()] >= heights[i]) {
        st.pop();
      }
      if (!st.empty())
        ans[i] = st.top();
      else
        ans[i] = n;
      st.push(i);
    }
    return ans;
  }
  vector<int> lsef(vector<int>& heights) {
    int n = heights.size();
    vector<int> ans(n);
    stack<int> st;
    for (int i = 0; i < n; i++) {
      while (!st.empty() && heights[st.top()] >= heights[i]) {
        st.pop();
      }
      if (!st.empty())
        ans[i] = st.top();
      else
        ans[i] = -1;
      st.push(i);
    }
    return ans;
  }

 public:
  int largestRectangleArea(vector<int>& heights) {
    int n = heights.size();
    vector<int> lse = lsef(heights);
    vector<int> nse = nsef(heights);
    int maxarea = 0;
    for (int i = 0; i < n; i++) {
      int width = nse[i] - lse[i] - 1;
      int height = heights[i];
      int area = width * height;
      maxarea = max(maxarea, area);
    }
    return maxarea;
  }
};

class Solution {
  vector<int> NSL(vector<int> vc) {
    stack<pair<int, int>> s;
    int size = vc.size();
    vector<int> v;
    for (int i = 0; i < size; i++) {
      while (!s.empty() && s.top().first >= vc[i]) {
        s.pop();
      }
      if (s.size() == 0) {
        v.push_back(-1);
      } else if (s.size() > 0 && s.top().first < vc[i]) {
        v.push_back(s.top().second);
      }
      s.push({vc[i], i});
    }
    return v;
  }
  vector<int> NSR(vector<int> vc) {
    stack<pair<int, int>> s;
    int size = vc.size();
    vector<int> v;
    int side = size;
    for (int i = size - 1; i >= 0; i--) {
      while (!s.empty() && s.top().first >= vc[i]) {
        s.pop();
      }
      if (s.size() == 0) {
        v.push_back(side);
      } else if (s.size() > 0 && s.top().first < vc[i]) {
        v.push_back(s.top().second);
      }
      s.push({vc[i], i});
    }
    reverse(v.begin(), v.end());
    return v;
  }
  int MAH(vector<int> vc) {
    int size = vc.size();
    vector<int> left = NSL(vc);
    vector<int> right = NSR(vc);
    vector<int> v(vc.size(), 0);
    int maxArea = 0;
    for (int i = 0; i < size; i++) {
      int area = vc[i] * (right[i] - left[i] - 1);
      maxArea = max(area, maxArea);
    }
    return maxArea;
  }

 public:
  int maximalRectangle(vector<vector<char>>& matrix) {
    if (matrix.empty()) return 0;

    int rows = matrix.size();
    int cols = matrix[0].size();

    vector<int> v(cols, 0);

    // Build histogram for first row
    for (int j = 0; j < cols; j++) {
      v[j] = (matrix[0][j] == '1') ? 1 : 0;
    }

    int mx = MAH(v);

    // Remaining rows
    for (int i = 1; i < rows; i++) {
      for (int j = 0; j < cols; j++) {
        if (matrix[i][j] == '0') {
          v[j] = 0;
        } else {
          v[j] += 1;
        }
      }
      mx = max(mx, MAH(v));
    }
    return mx;
  }
};

