 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
  vector<int> ans;
  void inorder(TreeNode* root) {
    if (root == NULL) return;
    inorder(root->left);
    ans.push_back(root->val);
    inorder(root->right);
  }

 public:
  vector<int> inorderTraversal(TreeNode* root) {
    inorder(root);
    return ans;
  }
};

class Solution {
  bool rec(string s1, string s2, string s3, int i, int j,
           vector<vector<int>>& dp) {
    // if(s1==""&&s2==""&&s3=="") return true;
    if (i < 0 && j < 0) return true;
    // if(i<0||j<0||k<0) return false;
    int k = i + j + 1;
    bool ans1 = false, ans2 = false;
    if (i >= 0 && j >= 0 && dp[i][j] != -1) {
      return dp[i][j];
    }
    if (i >= 0 && s1[i] == s3[k]) {
      cout << 1 << ", ";
      ans1 = rec(s1, s2, s3, i - 1, j, dp);
    }
    if (j >= 0 && s2[j] == s3[k]) {
      cout << 2 << ", ";
      ans2 = rec(s1, s2, s3, i, j - 1, dp);
    }
    if (i >= 0 && j >= 0) dp[i][j] = ans1 || ans2;

    return ans1 || ans2;
  }

 public:
  bool isInterleave(string s1, string s2, string s3) {
    int n1 = s1.size(), n2 = s2.size(), n3 = s3.size();
    vector<vector<int>> dp(n1 + 1, vector<int>(n2 + 1, -1));

    if (n1 + n2 != n3) {
      return false;
    }
    if (n1 == 1 && n2 == 0) return s1 == s3;
    if (n1 == 0 && n2 == 1) return s2 == s3;
    return rec(s1, s2, s3, s1.size() - 1, s2.size() - 1, dp);
  }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
 public:
  bool check(TreeNode* root, long l, long r) {
    if (root == NULL) return true;
    if (root->val <= l || root->val >= r) {
      return false;
    }
    return check(root->left, l, root->val) && check(root->right, root->val, r);
  }
  bool isValidBST(TreeNode* root) { return check(root, LONG_MIN, LONG_MAX); }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
 public:
  bool isSameTree(TreeNode* p, TreeNode* q) {
    if (p == NULL && q == NULL) {
      return true;
    }
    if (p == NULL || q == NULL) {
      return false;
    }

    bool ans = false;
    if (p->val == q->val) {
      ans = true;
    }
    ans = ans && isSameTree(p->right, q->right);
    ans = ans && isSameTree(p->left, q->left);
    return ans;
  }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
  bool isMirror(TreeNode* a, TreeNode* b) {
    bool ans = true;
    if (a == NULL && b == NULL) {
      return true;
    }
    if (a == NULL || b == NULL) {
      return false;
    }
    if (a->val != b->val) ans = false;
    ans &= isMirror(a->left, b->right);
    ans &= isMirror(a->right, b->left);
    return ans;
  }

 public:
  bool isSymmetric(TreeNode* root) { return isMirror(root->left, root->right); }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
 public:
  vector<vector<int>> levelOrder(TreeNode* root) {
    if (root == NULL) return {};
    vector<vector<int>> ans;
    queue<TreeNode*> q;
    q.push(root);
    while (!q.empty()) {
      int size = q.size();
      vector<int> level;
      for (int i = 0; i < size; i++) {
        TreeNode* node = q.front();
        q.pop();
        level.push_back(node->val);
        if (node->left != NULL) q.push(node->left);
        if (node->right != NULL) q.push(node->right);
      }
      ans.push_back(level);
    }
    return ans;
  }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
 public:
  vector<vector<int>> zigzagLevelOrder(TreeNode* root) {
    if (root == NULL) return {};
    vector<vector<int>> ans;
    stack<TreeNode*> curr, next;
    bool ltr = true;
    curr.push(root);
    vector<int> a;
    while (!curr.empty()) {
      TreeNode* t = curr.top();
      curr.pop();

      if (t) {
        a.push_back(t->val);
      }
      if (ltr) {
        if (t->left != NULL) {
          next.push(t->left);
        }
        if (t->right) {
          next.push(t->right);
        }
      } else {
        if (t->right) {
          next.push(t->right);
        }
        if (t->left) {
          next.push(t->left);
        }
      }
      if (curr.empty()) {
        ltr = !ltr;
        swap(curr, next);
        ans.push_back(a);
        a.clear();
      }
    }
    return ans;
  }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
  int maxdep(TreeNode* root, int size) {
    if (!root) return size;
    size = size + 1;
    int ls, rs;
    if (root->left) {
      ls = maxdep(root->left, size);
    } else {
      ls = size;
    }
    if (root->right) {
      rs = maxdep(root->right, size);
    } else {
      rs = size;
    }
    return max(ls, rs);
  }

 public:
  int maxDepth(TreeNode* root) { return maxdep(root, 0); }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
  TreeNode* rec(vector<int>& preorder, vector<int>& inorder, int start, int end,
                int& idx) {
    if (start > end) {
      return NULL;
    }
    int rootVal = preorder[idx];
    int i = start;
    for (; i <= end; i++) {
      if (inorder[i] == rootVal) {
        break;
      }
    }
    idx++;
    TreeNode* root = new TreeNode(rootVal);
    root->left = rec(preorder, inorder, start, i - 1, idx);
    root->right = rec(preorder, inorder, i + 1, end, idx);

    return root;
  }

 public:
  TreeNode* buildTree(vector<int>& preorder, vector<int>& inorder) {
    int n = preorder.size();
    int idx = 0;
    return rec(preorder, inorder, 0, n - 1, idx);
  }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
  int height(TreeNode* root) {
    if (root == NULL) return 0;
    int left = height(root->left);
    int right = height(root->right);
    if (left == -1 || right == -1) {
      return -1;
    }
    if (abs(left - right) > 1) {
      return -1;
    }
    return 1 + max(left, right);
  }

 public:
  bool isBalanced(TreeNode* root) { return height(root) != -1; }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
  int rec(TreeNode* root, int i) {
    int left = 1e9, right = 1e9;

    if (root->left == NULL && root->right == NULL) {
      return i;
    }
    if (root->left != NULL) {
      left = rec(root->left, i + 1);
    }
    if (root->right != NULL) {
      right = rec(root->right, i + 1);
    }
    return min(left, right);
  }

 public:
  int minDepth(TreeNode* root) {
    if (root == NULL) return 0;
    return 1 + rec(root, 0);
  }
};

/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
  bool checkPathSum(TreeNode* root, int targetSum) {
    if (root == NULL) {
      return false;
    }
    if (root->left == NULL && root->right == NULL) {
      return targetSum == root->val;
    }
    return checkPathSum(root->left, targetSum - root->val) ||
           checkPathSum(root->right, targetSum - root->val);
  }

 public:
  bool hasPathSum(TreeNode* root, int targetSum) {
    if (root == NULL) {
      return false;
    }
    return checkPathSum(root, targetSum);
  }
};

class Solution {
  int n, m;
  string s, t;
  vector<vector<long long>> dp;
  int rec(int i, int j) {
    if (j == m) return 1;
    if (i == n) return 0;
    if (dp[i][j] != -1) return dp[i][j];
    long long notTake = rec(i + 1, j);
    long long take = rec(i + 1, j + 1);
    if (s[i] == t[j]) {
      return dp[i][j] = take + notTake;
    }
    return dp[i][j] = notTake;
  }

 public:
  int numDistinct(string s, string t) {
    this->s = s;
    this->t = t;
    n = s.size(), m = t.size();
    dp.assign(n, vector<long long>(m, -1));
    return rec(0, 0);
  }
};

