class Solution {
 public:
  Node* connect(Node* root) {
    if (root == NULL) return NULL;
    queue<Node*> q;
    q.push(root);
    while (!q.empty()) {
      Node* curr;
      int n = q.size();
      while (n--) {
        curr = q.front();
        q.pop();
        curr->next = q.front();
        if (curr->left) q.push(curr->left);
        if (curr->right) q.push(curr->right);
      }
      curr->next = NULL;
    }
    return root;
  }
};

class Solution {
 public:
  vector<vector<int>> generate(int numRows) {
    vector<vector<int>> ans(numRows);
    for (int i = 0; i < numRows; i++) {
      ans[i] = vector<int>(i + 1, 1);
      for (int j = 1; j < i; j++) {
        ans[i][j] = ans[i - 1][j - 1] + ans[i - 1][j];
      }
    }
    return ans;
  }
};

class Solution {
 public:
  vector<int> getRow(int n) {
    vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
    for (int i = 0; i <= n; i++) {
      dp[i][i] = 1;
      dp[i][0] = 1;
    }
    for (int i = 1; i <= n; i++) {
      for (int j = 1; j < i; j++) {
        dp[i][j] = dp[i - 1][j] + dp[i - 1][j - 1];
      }
    }
    return dp[n];
  }
};

class Solution {
 public:
  int minimumTotal(vector<vector<int>>& triangle) {
    int n = triangle.size();
    vector<int> dp(triangle.back());

    for (int i = n - 2; i >= 0; i--) {
      for (int j = 0; j < triangle[i].size(); j++) {
        dp[j] = triangle[i][j] + min(dp[j], dp[j + 1]);
      }
    }

    return dp[0];
  }
};

class Solution {
 public:
  int maxProfit(vector<int>& prices) {
    int ans = 0;
    int n = prices.size();
    int bestBuy = prices[0];
    for (int i = 1; i < n; i++) {
      bestBuy = min(prices[i - 1], bestBuy);
      ans = max(ans, prices[i] - bestBuy);
    }
    return ans;
  }
};

class Solution {
  vector<int> prices;
  int n;
  vector<vector<int>> dp;
  int buy(int i, bool canBuy) {
    int profit = 0;
    if (i == n) {
      return 0;
    }
    if (dp[i][canBuy] != -1) return dp[i][canBuy];
    if (canBuy) {
      profit = max(buy(i + 1, false) - prices[i], buy(i + 1, true));
    } else {
      profit = max(buy(i + 1, true) + prices[i], buy(i + 1, false));
    }
    return dp[i][canBuy] = profit;
  }

 public:
  int maxProfit(vector<int>& prices) {
    this->prices = prices;
    n = prices.size();
    dp.assign(n, vector<int>(2, -1));
    return buy(0, true);
  }
};

class Solution {
 public:
  bool isPalindrome(string s) {
    string z;
    for (int i = 0; i < s.length(); i++) {
      if (isalnum(s[i])) {
        if (isupper(s[i])) {
          z.push_back(tolower(s[i]));

        } else {
          z.push_back(s[i]);
        }
      }
    }

    int i = 0;
    int j = z.length() - 1;
    bool is = true;
    while (i < j) {
      if (z[i] != z[j]) is = false;
      i++;
      j--;
    }

    return is;
  }
};

class Solution {
 public:
  int longestConsecutive(vector<int>& nums) {
    sort(nums.begin(), nums.end());
    int size = nums.size();
    int seq = 0;
    int lSeq = 0;
    if (size == 0) return 0;
    for (int i = 0; i < size - 1; i++) {
      if (nums[i + 1] - 1 == nums[i]) {
        seq++;
      } else if (nums[i + 1] == nums[i]) {
        continue;
      } else {
        seq = 0;
      }
      lSeq = max(seq, lSeq);
    }
    return lSeq + 1;
  }
};

class Solution {
  vector<vector<string>> ans;
  bool isPal(int i, int j, string s) {
    if (i >= j) return true;
    if (s[i] == s[j]) {
      return isPal(i + 1, j - 1, s);
    } else {
      return false;
    }
  }
  void solve(int idx, string &s, vector<string> path) {
    if (idx == s.size()) {
      ans.push_back(path);
    }
    for (int j = idx; j < s.size(); j++) {
      if (isPal(idx, j, s)) {
        path.push_back(s.substr(idx, j - idx + 1));
        solve(j + 1, s, path);
        path.pop_back();
      }
    }
  }

 public:
  vector<vector<string>> partition(string s) {
    vector<string> path;
    solve(0, s, path);
    return ans;
  }
};

