class Solution {
 public:
  int evalRPN(vector<string>& tokens) {
    stack<int> st;
    for (auto token : tokens) {
      if (token == "+" || token == "-" || token == "*" || token == "/") {
        int b = st.top();
        st.pop();
        int a = st.top();
        st.pop();
        if (token == "+")
          st.push(a + b);
        else if (token == "-")
          st.push(a - b);
        else if (token == "*")
          st.push(a * b);
        else
          st.push(a / b);

      } else
        (st.push(stoi(token)));
    }
    return st.top();
  }
};

class Solution {
 public:
  int findMin(vector<int>& nums) {
    int n = nums.size();
    int st = 0, end = n - 1, mid;
    int ans = INT_MAX;
    while (st <= end) {
      mid = st + (end - st) / 2;
      if (nums[st] <= nums[end]) {
        ans = min(ans, nums[st]);
        return ans;
      }
      if (nums[mid] <= nums[end]) {
        ans = min(ans, nums[mid]);
        end = mid - 1;
      } else {
        ans = min(ans, nums[mid]);
        st = mid + 1;
      }
    }
    return ans;
  }
};

class Solution {
 public:
  int findMin(vector<int>& nums) {
    int l = 0, r = nums.size() - 1;
    while (l < r) {
      int mid = l + (r - l) / 2;
      if (nums[mid] > nums[r]) {
        l = mid + 1;
      } else if (nums[mid] < nums[r]) {
        r = mid;
      } else {
        r--;
      }
    }
    return nums[l];
  }
};

class MinStack {
 public:
  stack<long long> st;
  long long min;
  MinStack() {}

  void push(int val) {
    if (st.empty()) {
      st.push(val);
      min = val;
      return;
    }
    if (val >= min) {
      st.push(val);
    } else {
      st.push((long long)2 * val - min);
      min = val;
    }
    return;
  }

  void pop() {
    if (st.empty()) {
      return;
    }
    if (st.top() < min) {
      long long top = st.top();
      st.pop();
      min = 2 * min - top;
    } else {
      st.pop();
    }
  }

  int top() {
    if (st.top() < min) {
      return min;
    } else {
      return st.top();
    }
  }

  int getMin() { return min; }
};

