/**
 * Definition for a binary tree node.
 * struct TreeNode {
 *     int val;
 *     TreeNode *left;
 *     TreeNode *right;
 *     TreeNode() : val(0), left(nullptr), right(nullptr) {}
 *     TreeNode(int x) : val(x), left(nullptr), right(nullptr) {}
 *     TreeNode(int x, TreeNode *left, TreeNode *right) : val(x), left(left),
 * right(right) {}
 * };
 */
class Solution {
 public:
  TreeNode* invertTree(TreeNode* root) {
    if (root == NULL) {
      return NULL;
    }
    TreeNode* left = root->left;
    TreeNode* right = root->right;
    root->left = right;
    root->right = left;
    invertTree(root->left);
    invertTree(root->right);
    return root;
  }
};

class Solution {
 public:
  int calculate(string s) {
    int currNo = 0;
    int n = s.size();
    char op = '+';
    stack<int> st;
    for (int i = 0; i < n; i++) {
      char currChar = s[i];
      if (isdigit(currChar)) {
        currNo *= 10;
        currNo += currChar - '0';
      }
      if (!isdigit(currChar) && !isspace(currChar) || i == n - 1) {
        if (op == '-') {
          st.push(-currNo);
        } else if (op == '+') {
          st.push(currNo);
        } else if (op == '*') {
          int top = st.top();
          st.pop();

          st.push(currNo * top);
        } else if (op == '/') {
          int top = st.top();
          st.pop();
          st.push(top / currNo);
        }
        op = currChar;
        currNo = 0;
      }
    }
    int ans = 0;
    while (!st.empty()) {
      ans += st.top();
      st.pop();
    }
    return ans;
  }
};

