class Solution {
 public:
  vector<int> productExceptSelf(vector<int>& nums) {
    vector<int> answer(nums.size(), 1);
    int prefix = 1;
    int n = nums.size();
    for (int i = 0; i < n; i++) {
      answer[i] = prefix;
      prefix *= nums[i];
    }
    int suffix = 1;
    for (int i = n - 1; i >= 0; i--) {
      answer[i] *= suffix;
      suffix *= nums[i];
    }
    return answer;
  }
};

class Solution {
 public:
  vector<int> maxSlidingWindow(vector<int>& nums, int k) {
    deque<int> q;
    vector<int> ans;
    int l = 0, r = 0;
    int n = nums.size();
    while (r < n) {
      while (!q.empty() && nums[q.back()] < nums[r]) {
        q.pop_back();
      }
      q.push_back(r);
      if (!q.empty() && q.front() < l) {
        q.pop_front();
      }
      if (r - l + 1 == k) {
        ans.push_back(nums[q.front()]);
        l++;
      }
      r++;
    }
    return ans;
  }
};

