class Solution {
 public:
  bool wordPattern(string pattern, string s) {
    stringstream ss(s);
    vector<string> sa;
    string word;
    while (ss >> word) {
      sa.push_back(word);
    }

    if (sa.size() != pattern.size()) return false;

    map<char, string> cs;
    map<string, char> sc;

    for (int i = 0; i < pattern.size(); i++) {
      char c = pattern[i];
      string w = sa[i];

      if (cs.find(c) != cs.end()) {
        if (cs[c] != w) return false;
      } else {
        cs[c] = w;
      }

      if (sc.find(w) != sc.end()) {
        if (sc[w] != c) return false;
      } else {
        sc[w] = c;
      }
    }

    return true;
  }
};

class MedianFinder {
 public:
  priority_queue<int> leftMax;
  priority_queue<int, vector<int>, greater<int>> rightMin;

  MedianFinder() {}

  void addNum(int num) {
    leftMax.push(num);
    rightMin.push(leftMax.top());
    leftMax.pop();
    if (rightMin.size() > leftMax.size()) {
      leftMax.push(rightMin.top());
      rightMin.pop();
    }
  }

  double findMedian() {
    if (leftMax.size() > rightMin.size()) {
      return leftMax.top();
    }
    return (leftMax.top() + rightMin.top()) / 2.0;
  }
};

class Solution {
 public:
  int lengthOfLIS(vector<int>& nums) {
    int n = nums.size();
    vector<vector<int>> dp(n + 1, vector<int>(n + 1, 0));
    for (int i = n - 1; i >= 0; i--) {
      for (int pre = i - 1; pre >= -1; pre--) {
        int notTake = dp[i + 1][pre + 1];
        int take = 0;
        if (pre == -1 || nums[i] > nums[pre]) {
          take = 1 + dp[i + 1][i + 1];
        }
        dp[i][pre + 1] = max(take, notTake);
      }
    }
    return dp[0][0];
  }
};

