      last[s[i] - 'a'] = i;
    }
    vector<bool> used(26, false);
    string ans;
    for (int i = 0; i < n; i++) {
      char ch = s[i];
      if (used[ch - 'a']) continue;
      while (!ans.empty() && ch < ans.back() && last[ans.back() - 'a'] > i) {
