  int maxRotateFunction(vector<int>& nums) {
    int n = nums.size();
    int sum = 0;
    int f = 0;
    for (int t = 0; t < n; t++) {
      sum += nums[t];
    }
    for (int t = 0; t < n; t++) {
      f += t * nums[t];
    }
    int a = f;
