      mp[e[i][0]].push_back({e[i][1], v[i]});
      mp[e[i][1]].push_back({e[i][0], 1 / v[i]});
    }
    int m = q.size();
    vector<double> ans;
    for (int i = 0; i < m; i++) {
      if (mp.find(q[i][0]) == mp.end() || mp.find(q[i][1]) == mp.end()) {
        ans.push_back(-1);
