class Solution {
 public:
  int trapRainWater(vector<vector<int>>& heightMap) {
    if (heightMap.empty() || heightMap[0].empty()) return 0;
    int m = heightMap.size(), n = heightMap[0].size();
    if (m < 3 || n < 3) return 0;

    using T = tuple<int, int, int>;
    priority_queue<T, vector<T>, greater<T>> pq;
    vector<vector<bool>> visited(m, vector<bool>(n, false));

    for (int i = 0; i < m; ++i) {
      pq.emplace(heightMap[i][0], i, 0);
      visited[i][0] = true;
      pq.emplace(heightMap[i][n - 1], i, n - 1);
      visited[i][n - 1] = true;
    }
    for (int j = 0; j < n; ++j) {
      if (!visited[0][j]) {
        pq.emplace(heightMap[0][j], 0, j);
        visited[0][j] = true;
      }
      if (!visited[m - 1][j]) {
        pq.emplace(heightMap[m - 1][j], m - 1, j);
        visited[m - 1][j] = true;
      }
    }

    int res = 0;
    int dirs[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    while (!pq.empty()) {
      auto [h, r, c] = pq.top();
      pq.pop();
      for (auto& d : dirs) {
        int nr = r + d[0], nc = c + d[1];
        if (nr < 0 || nr >= m || nc < 0 || nc >= n || visited[nr][nc]) continue;
        visited[nr][nc] = true;
        int nh = heightMap[nr][nc];
        if (nh < h) res += h - nh;
        pq.emplace(max(nh, h), nr, nc);
      }
    }
    return res;
  }
};

class Solution {
 public:
  int longestPalindrome(string s) {
    int ans = 0;

    unordered_map<char, int> mp;
    for (auto ch : s) {
      mp[ch]++;
    }
    int one = 0;
    for (auto it : mp) {
      int i = it.second;
      if (i % 2 == 0) {
        ans += i;
      } else if (i % 2 == 1) {
        ans += i - 1;
        one = 1;
      }
    }
    return ans + one;
  }
};

class Solution {
  bool can(vector<int>& nums, int i, int target, vector<vector<int>>& dp) {
    if (target == 0) {
      return true;
    }
    if (target < 0) {
      return false;
    }
    int n = nums.size();
    if (i == n) {
      return false;
    }
    if (dp[i][target] != -1) {
      return (bool)dp[i][target];
    }
    int take = 0, notTake = 0;
    take = can(nums, i + 1, target - nums[i], dp);
    notTake = can(nums, i + 1, target, dp);
    return dp[i][target] = (int)(take || notTake);
  }

 public:
  bool canPartition(vector<int>& nums) {
    int n = nums.size();
    int sum = accumulate(nums.begin(), nums.end(), 0);
    if (sum % 2 != 0) return false;
    int target = sum / 2;
    vector<vector<int>> dp(n + 1, vector<int>(target + 1, -1));
    return can(nums, 0, target, dp);
  }
};

