class Solution {
 public:
  int m, n;
  vector<vector<int>> dirs = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

  void dfs(vector<vector<int>>& heights, int r, int c,
           vector<vector<bool>>& visited) {
    visited[r][c] = true;
    for (auto& d : dirs) {
      int nr = r + d[0];
      int nc = c + d[1];
      if (nr >= 0 && nr < m && nc >= 0 && nc < n && !visited[nr][nc] &&
          heights[nr][nc] >= heights[r][c]) {
        dfs(heights, nr, nc, visited);
      }
    }
  }

  vector<vector<int>> pacificAtlantic(vector<vector<int>>& heights) {
    m = heights.size();
    n = heights[0].size();

    vector<vector<bool>> pac(m, vector<bool>(n, false));
    vector<vector<bool>> atl(m, vector<bool>(n, false));

    for (int i = 0; i < m; i++) dfs(heights, i, 0, pac);
    for (int j = 0; j < n; j++) dfs(heights, 0, j, pac);

    for (int i = 0; i < m; i++) dfs(heights, i, n - 1, atl);
    for (int j = 0; j < n; j++) dfs(heights, m - 1, j, atl);

    vector<vector<int>> result;
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        if (pac[i][j] && atl[i][j]) {
          result.push_back({i, j});
        }
      }
    }
    return result;
  }
};

class Solution {
  struct Trie {
    Trie* left;
    Trie* right;
  };
  void insert(Trie* root, int num) {
    Trie* curr = root;
    for (int i = 31; i >= 0; i--) {
      int ithBit = (num >> i) & 1;
      if (ithBit == 0) {
        if (curr->left == NULL) {
          curr->left = new Trie();
        }
        curr = curr->left;
      } else {
        if (curr->right == NULL) {
          curr->right = new Trie();
        }
        curr = curr->right;
      }
    }
  }
  int get(Trie* root, int num) {
    int ans = 0;
    Trie* curr = root;
    for (int i = 31; i >= 0; i--) {
      int ithBit = (num >> i) & 1;
      if (ithBit == 0) {
        if (curr->right != NULL) {
          curr = curr->right;
          ans = ans | 1 << i;

        } else if (curr->left != NULL) {
          curr = curr->left;
        } else {
          return ans;
        }

      } else {
        if (curr->left != NULL) {
          curr = curr->left;
          ans = ans | 1 << i;

        } else if (curr->right != NULL) {
          curr = curr->right;
        } else {
          return ans;
        }
      }
    }
    return ans;
  }

 public:
  int findMaximumXOR(vector<int>& nums) {
    Trie* root = new Trie();
    int n = nums.size();
    int maxAns = 0;
    for (int i = 0; i < n; i++) {
      insert(root, nums[i]);
    }
    for (int j = 0; j < n; j++) {
      maxAns = max(maxAns, get(root, nums[j]));
    }
    return maxAns;
  }
};

class Solution {
 public:
  int characterReplacement(string s, int k) {
    unordered_map<char, int> mp;
    int n = s.size();
    int l = 0, r = 0;
    int maxSize = 0;
    int maxFreq = 0;
    while (r < n) {
      mp[s[r]]++;
      maxFreq = max(maxFreq, mp[s[r]]);
      r++;
      while ((r - l) - maxFreq > k) {
        mp[s[l]]--;
        l++;
      }

      maxSize = max(maxSize, r - l);
    }
    return maxSize;
  }
};

