class Solution {
  vector<int> buildLPS(string b) {
    int n = b.size();
    vector<int> lps(n, 0);
    int len = 0;
    for (int i = 1; i < n; i++) {
      if (b[i] == b[len]) {
        len++;
        lps[i] = len;
      } else {
        if (len == 0) {
          lps[i] = 0;
        } else {
          i--;
          len = lps[len - 1];
        }
      }
    }
    return lps;
  }
  bool kmpSearch(string a, string b, vector<int>& lps) {
    int n = a.size();
    int m = b.size();
    int i = 0, j = 0;
    while (i < n) {
      if (a[i] == b[j]) {
        i++;
        j++;
      }
      if (j == m) {
        return true;
      } else if (a[i] != b[j]) {
        if (j != 0) {
          j = lps[j - 1];
        } else {
          i++;
        }
      }
    }
    return false;
  }

 public:
  int repeatedStringMatch(string a, string b) {
    int cnt = 1;
    vector<int> lps = buildLPS(b);
    string r = a;
    while (r.size() < b.size()) {
      r += a;
      cnt++;
    }
    if (kmpSearch(r, b, lps)) {
      return cnt;
    }
    r += a;
    cnt++;
    if (kmpSearch(r, b, lps)) {
      return cnt;
    }
    return -1;
  }
};

class Solution {
 public:
  bool hasAlternatingBits(int n) {
    bool pre = false;
    if (n & 1) {
      pre = true;
    }
    n = n >> 1;
    bool curr = false;
    while (n) {
      if (n & 1) {
        curr = true;
      } else {
        curr = false;
      }
      n = n >> 1;
      if (curr == pre) {
        return false;
      }
      pre = curr;
    }
    return true;
  }
};

class Solution {
  int solve(string &s1, string &s2, int i, int j, vector<vector<int>> &dp) {
    if (i < 0 && j < 0) return 0;
    if (i < 0) return s2[j] + solve(s1, s2, i, j - 1, dp);
    if (j < 0) return s1[i] + solve(s1, s2, i - 1, j, dp);

    if (dp[i][j] != -1) return dp[i][j];

    if (s1[i] == s2[j]) {
      return dp[i][j] = solve(s1, s2, i - 1, j - 1, dp);
    }

    return dp[i][j] = min(s1[i] + solve(s1, s2, i - 1, j, dp),
                          s2[j] + solve(s1, s2, i, j - 1, dp));
  }

 public:
  int minimumDeleteSum(string s1, string s2) {
    int n = s1.length();
    int m = s2.length();

    vector<vector<int>> dp(n, vector<int>(m, -1));
    return solve(s1, s2, n - 1, m - 1, dp);
  }
};

class Solution {
 public:
  int numSubarrayProductLessThanK(vector<int>& nums, int k) {
    int n = nums.size();
    int l = 0;
    int r = 0;
    long long Product = 1;
    int cnt = 0;
    if (k <= 1) return 0;
    while (r < n) {
      Product *= nums[r];
      r++;
      while (Product >= k) {
        Product /= nums[l];
        l++;
      }
      cnt += (r - l);
    }
    return cnt;
  }
};

class Solution {
 public:
  int dp[50001][2];
  int rec(vector<int>& prices, int i, int canBuy, int fee) {
    if (i == prices.size()) return 0;
    if (dp[i][canBuy] != -1) return dp[i][canBuy];
    int profit = 0;
    if (canBuy) {
      int buy = -prices[i] + rec(prices, i + 1, 0, fee);
      int skip = rec(prices, i + 1, 1, fee);
      profit = max(buy, skip);
    } else {
      int sell = prices[i] - fee + rec(prices, i + 1, 1, fee);
      int skip = rec(prices, i + 1, 0, fee);
      profit = max(sell, skip);
    }
    return dp[i][canBuy] = profit;
  }
  int maxProfit(vector<int>& prices, int fee) {
    memset(dp, -1, sizeof(dp));
    return rec(prices, 0, 1, fee);
  }
};

