      return dp[i][j];
    }
    double leftSide = max(0.0, (rec(i - 1, j - 1, dp) - 1.0) / 2.0);
    double rightSide = max(0.0, (rec(i - 1, j, dp) - 1.0) / 2.0);

    return dp[i][j] = leftSide + rightSide;
  }

