        while (cmd--) {
          int nx = x + directions[dir].first;
          int ny = y + directions[dir].second;
          if (blocked.count({nx, ny})) break;
          x = nx;
          y = ny;
          maxDist = max(maxDist, x * x + y * y);
        }
      }
    }

    return maxDist;
  }
};

class Solution {
