class TreeAncestor {
  vector<vector<int>> up;
  int row, col;

 public:
  TreeAncestor(int n, vector<int>& parent) {
    row = n;
    col = log2(n) + 1;
    up.assign(row, vector<int>(col, -1));
    for (int i = 0; i < row; i++) {
      up[i][0] = parent[i];
    }
    for (int j = 1; j < col; j++) {
      for (int i = 0; i < row; i++) {
        if (up[i][j - 1] != -1) {
          up[i][j] = up[up[i][j - 1]][j - 1];
        }
      }
    }
  }

  int getKthAncestor(int node, int k) {
    for (int i = 0; i < col; i++) {
      if (k & (1 << i)) {
        node = up[node][i];
        if (node == -1) {
          return -1;
        }
      }
    }
    return node;
  }
};

