    k %= size;
    if (k == 0) {
      return grid;
    }
    auto reverse = [&](int i, int j) {
      while (i < j) {
        swap(grid[i / n][i % n], grid[j / n][j % n]);
        i++;
        j--;
      }
    };
    reverse(0, size - 1);
    reverse(0, k - 1);
    reverse(k, size - 1);

