class DSU {
  vector<int> parent;
  vector<int> size;

 public:
  DSU(int n) {
    size.assign(n, 1);
    parent.resize(n);
    iota(parent.begin(), parent.end(), 0);
  }
  int find(int n) {
    if (parent[n] == n) {
      return n;
    }
    return parent[n] = find(parent[n]);
  }
  void unite(int i, int j) {
    i = find(i);
    j = find(j);
    if (i == j) return;
    if (size[i] > size[j]) {
      swap(i, j);
    }
    size[j] += size[i];
    parent[i] = j;
  }
};

