    int n = grid.size();
    int m = grid[0].size();
    vector<vector<bool>> vis(n + 1, vector<bool>(m + 1, false));
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (!vis[i][j] && dfs(i, j, -1, -1, grid, vis)) {
          return true;
        }
      }
    }
    return false;
  }
};

