class Solution {
  int solve(int l, int r, vector<int>& cuts, vector<vector<int>>& dp) {
    if (r - l <= 1) {
      return 0;
    }
    if (dp[l][r] != -1) {
      return dp[l][r];
    }
    int ans = 1e9;
    for (int i = l + 1; i < r; i++) {
      int cost =
          cuts[r] - cuts[l] + solve(l, i, cuts, dp) + solve(i, r, cuts, dp);
      ans = min(cost, ans);
    }
    return dp[l][r] = ans;
  }

 public:
  int minCost(int n, vector<int>& cuts) {
    sort(cuts.begin(), cuts.end());
    cuts.insert(cuts.begin(), 0);
    cuts.push_back(n);
    int size = cuts.size();
    vector<vector<int>> dp(size + 1, vector<int>(size + 1, -1));
    return solve(0, size - 1, cuts, dp);
  }
};

class Solution {
  vector<vector<int>> dp;
  int n;
  vector<int> pref;
  int solve(int l, int r) {
    if (l >= r) {
      return 0;
    }
    if (dp[l][r] != -1) {
      return dp[l][r];
    }
    int ans = 0;
    for (int mid = l; mid < r; mid++) {
      int left = pref[mid] - (l ? pref[l - 1] : 0);
      int right = pref[r] - pref[mid];
      if (left > right) {
        ans = max(ans, right + solve(mid + 1, r));
      } else if (right > left) {
        ans = max(ans, left + solve(l, mid));
      } else {
        ans = max({ans, right + solve(mid + 1, r), left + solve(l, mid)});
      }
    }
    return dp[l][r] = ans;
  }

 public:
  int stoneGameV(vector<int>& stoneValue) {
    int score = 0;
    int n = stoneValue.size();
    dp.assign(n, vector<int>(n, -1));
    int sum = 0;
