class Solution {
 public:
  int maxProductPath(vector<vector<int>>& grid) {
    int n = grid.size();
    int m = grid[0].size();
    vector<vector<long long>> maxDp(n, vector<long long>(m, 1));
    vector<vector<long long>> minDp(n, vector<long long>(m, 1));
    maxDp[0][0] = minDp[0][0] = grid[0][0];
    for (int i = 1; i < n; i++) {
      maxDp[i][0] = minDp[i][0] = grid[i][0] * maxDp[i - 1][0];
    }
    for (int i = 1; i < m; i++) {
      maxDp[0][i] = minDp[0][i] = grid[0][i] * maxDp[0][i - 1];
    }
    for (int i = 1; i < n; i++) {
      for (int j = 1; j < m; j++) {
        long long val = grid[i][j];
        long long a = maxDp[i - 1][j] * val;
        long long b = maxDp[i][j - 1] * val;
        long long c = minDp[i - 1][j] * val;
        long long d = minDp[i][j - 1] * val;
        maxDp[i][j] = max({a, b, c, d});
        minDp[i][j] = min({a, b, c, d});
      }
    }
    long long res = maxDp[n - 1][m - 1];
    if (res < 0)
      return -1;
    else {
      return res % 1000000007;
    }
  }
};

class Solution {
 public:
  int M = 1e9 + 7;
  int dp[1001][1001];

  int numberOfSets(int n, int K) {
    for (int i = 0; i <= n; i++) {
      dp[0][i] = (i < n) ? 1 : 0;
    }

    for (int k = 1; k <= K; k++) {
      vector<int> prevRowSum(n + 1, 0);

      // prevRowSum[x] = dp[k-1][x] + dp[k-1][x+1] + ... + dp[k-1][n-1]
      for (int x = n - 1; x >= 0; x--) {
        prevRowSum[x] = (prevRowSum[x + 1] + dp[k - 1][x]) % M;
      }

      for (int i = n - 1; i >= 0; i--) {
        int skip = dp[k][i + 1];

        int take = prevRowSum[i + 1];
        // dp[k-1][i+1] + dp[k-1][i+2] ...... + dp[k-1][n-1]

        dp[k][i] = (take + skip) % M;
      }
    }

    return dp[K][0];
  }
};

class Fancy {
  long long add = 0;
  long long mul = 1;
  const long long mod = 1e9 + 7;
  vector<long long> arr;
  long long modPow(long long a, long long b) {
    long long res = 1;
    while (b) {
      if (b & 1) res = (res * a) % mod;
      a = (a * a) % mod;
      b >>= 1;
    }
    return res;
  }

  long long modInverse(long long x) { return modPow(x, mod - 2); }

 public:
  Fancy() {}

  void append(int val) {
    long long x = ((val - add) % mod + mod) % mod;
    x = (x * modInverse(mul)) % mod;
    arr.push_back(x);
  }

  void addAll(int inc) { add = (add + inc) % mod; }

  void multAll(int m) {
    mul = (mul * m) % mod;
    add = (add * m) % mod;
  }

  int getIndex(int idx) {
    if (idx >= arr.size()) return -1;

    long long val = arr[idx];
    val = (val * mul) % mod;
    val = (val + add) % mod;

    return val;
  }
};

