  vector<int> pref;
  // i->left j->right position
  vector<vector<int>> dp;
  int rec(int i, int j) {
    if (i >= j) return 0;
    if (dp[i][j] != -1) return dp[i][j];
    // cout<<"i:- "<<i<<" j:-"<<j<<endl;
    int takeLeft = pref[j] - pref[i] - rec(i + 1, j);
