  int minOperations(string s) {
    int cnt1 = 0;
    for (int i = 0; i < s.length(); i++) {
      if (i % 2 == 0) {
        if (s[i] != '0') cnt1++;

      } else {
        if (s[i] != '1') {
          cnt1++;
        }
      }
    }
    int cnt2 = 0;
    for (int i = 0; i < s.length(); i++) {
      if (i % 2 == 0) {
        if (s[i] != '1') cnt2++;
      } else {
        if (s[i] != '0') {
          cnt2++;
        }
      }
    }
    return min(cnt1, cnt2);
  }
};

class Solution {
 public:
  bool checkOnesSegment(string s) {
    if (s[0] == '0') return false;
    int n = s.size();
    if (n == 1) return true;
    int cnt = 1;
    for (int i = 1; i < n; i++) {
      if (s[i] == '1') {
        if (s[i - 1] != s[i]) {
          cnt++;
        }
      }
    }
    if (cnt == 1) return true;
    return false;
  }
};

class Solution {
  unordered_map<string, string> mp;
  string getVal(string key) {
    if (mp.count(key)) {
      return mp[key];
    }
    return "?";
  }

 public:
  string evaluate(string s, vector<vector<string>>& knowledge) {
    for (auto& k : knowledge) {
      mp[k[0]] = k[1];
    }
    int n = s.size();
    string ans = "";
    for (int i = 0; i < n; i++) {
      if (s[i] == '(') {
        i++;
        string temp = "";
        while (i < n && s[i] != ')') {
          temp += s[i];
          i++;
        }
        ans += getVal(temp);

      } else {
        ans += s[i];
      }
    }
    return ans;
  }
};

class Solution {
 public:
  int maximumElementAfterDecrementingAndRearranging(vector<int>& arr) {
    sort(begin(arr), end(arr));
    arr[0] = 1;
    for (int i = 0; i < arr.size() - 1; i++) {
      if (arr[i + 1] > arr[i]) {
        arr[i + 1] = arr[i] + 1;
      }
      if (arr[i + 1] < arr[i]) {
        arr[i + 1] = arr[i] - 1;
      }
    }
    return *max_element(begin(arr), end(arr));
  }
};

