class Solution {
 public:
  int maxBuilding(int n, vector<vector<int>>& restrictions) {
    restrictions.push_back({1, 0});
    sort(restrictions.begin(), restrictions.end());
    if (restrictions.back()[0] != n) restrictions.push_back({n, n - 1});

    int m = restrictions.size();
    for (int i = 1; i < m; i++) {
      int dist = restrictions[i][0] - restrictions[i - 1][0];
      restrictions[i][1] =
          min(restrictions[i][1], restrictions[i - 1][1] + dist);
    }
    for (int i = m - 2; i >= 0; i--) {
      int dist = restrictions[i + 1][0] - restrictions[i][0];
      restrictions[i][1] =
          min(restrictions[i][1], restrictions[i + 1][1] + dist);
    }

    long long ans = 0;

    for (int i = 1; i < m; i++) {
      long long x1 = restrictions[i - 1][0];
      long long h1 = restrictions[i - 1][1];

      long long x2 = restrictions[i][0];
      long long h2 = restrictions[i][1];

      long long d = x2 - x1;
      ans = max(ans, (h1 + h2 + d) / 2);
    }

    return (int)ans;
  }
};

class Solution {
 public:
  vector<vector<char>> rotateTheBox(vector<vector<char>>& boxGrid) {
    int n = boxGrid.size();
    int m = boxGrid[0].size();
    vector<vector<char>> ans(m, vector<char>(n, '.'));
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        ans[j][n - i - 1] = boxGrid[i][j];
      }
    }
    for (int j = 0; j < n; j++) {
      for (int i = m - 1; i >= 0; i--) {
        if (ans[i][j] == '.') {
          for (int k = i - 1; k >= 0; k--) {
            if (ans[k][j] == '*') {
              break;
            }
            if (ans[k][j] == '#') {
              swap(ans[i][j], ans[k][j]);
              break;
            }
          }
        }
      }
    }
    return ans;
  }
};

class Solution {
 public:
  int getMinDistance(vector<int>& nums, int target, int start) {
    int ans = INT_MAX;
    for (int i = 0; i < nums.size(); i++) {
      if (nums[i] == target) {
        ans = min(ans, abs(i - start));
      }
    }
    return ans;
  }
};

class Solution {
 public:
  int maxDistance(vector<int>& nums1, vector<int>& nums2) {
    int i = 0;
    int j = 0;
    int dis = 0;
    while (i < nums1.size() && j < nums2.size()) {
      if (nums1[i] <= nums2[j]) {
        dis = max(dis, j - i);

        j++;
      } else {
        i++;
      }
    }
    return dis;
  }
};

class Solution {
 public:
  int minPairSum(vector<int>& nums) {
    int size = nums.size();
    sort(nums.begin(), nums.end());
    int maxNo = INT_MIN;
    for (int i = 0; i < size / 2; i++) {
      maxNo = max(nums[i] + nums[size - i - 1], maxNo);
    }
    return maxNo;
  }
};

class Solution {
 public:
  vector<int> getBiggestThree(vector<vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();

    vector<vector<int>> d1(m + 1, vector<int>(n + 1, 0));
    vector<vector<int>> d2(m + 1, vector<int>(n + 2, 0));

    for (int i = 1; i <= m; i++) {
      for (int j = 1; j <= n; j++) {
        d1[i][j] = grid[i - 1][j - 1] + d1[i - 1][j - 1];
      }
    }

    for (int i = 1; i <= m; i++) {
      for (int j = n; j >= 1; j--) {
        d2[i][j] = grid[i - 1][j - 1] + d2[i - 1][j + 1];
      }
    }

    set<int> s;

    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        s.insert(grid[i][j]);

        for (int k = 1;; k++) {
          int top_r = i - k;
          int bottom_r = i + k;
          int left_c = j - k;
          int right_c = j + k;

          if (top_r < 0 || bottom_r >= m || left_c < 0 || right_c >= n) break;

          int sum = 0;

          sum += d1[i + 1][right_c + 1] - d1[top_r][j];
          sum += d2[bottom_r + 1][j + 1] - d2[i][right_c + 2];
          sum += d1[bottom_r + 1][j + 1] - d1[i][left_c];
          sum += d2[i + 1][left_c + 1] - d2[top_r][j + 2];

          sum -= grid[top_r][j];
          sum -= grid[i][right_c];
          sum -= grid[bottom_r][j];
          sum -= grid[i][left_c];

          s.insert(sum);
        }
      }
    }

    vector<int> ans;
    for (auto it = s.rbegin(); it != s.rend() && ans.size() < 3; it++) {
      ans.push_back(*it);
    }

    return ans;
  }
};

class Solution {
  vector<int> pref;
  vector<int> nums;
  int n;
  vector<int> dp;
  int rec(int idx) {
    if (idx == n - 1) return pref[idx];
    if (dp[idx] != INT_MIN) return dp[idx];
    int next = rec(idx + 1);
    return dp[idx] = max(pref[idx] - next, next);
  }

 public:
  int stoneGameVIII(vector<int>& stones) {
    n = stones.size();
    pref.assign(n, 0);
    pref[0] = stones[0];
    for (int i = 0; i < n; i++) {
      if (i != 0) pref[i] = pref[i - 1] + stones[i];
      // cout<<pref[i]<<"  ";
    }
    nums = stones;
    dp.assign(n, INT_MIN);
    // cout<<ans<<endl;
    return rec(1);
  }
};

class Solution {
  void rotate(vector<vector<int>>& mat) {
    int n = mat.size();
    int m = mat[0].size();
    for (int i = 0; i < n; i++) {
      for (int j = i; j < m; j++) {
        swap(mat[i][j], mat[j][i]);
      }
    }
    for (int i = 0; i < n; i++) {
      reverse(mat[i].begin(), mat[i].end());
    }
  }
  bool check(vector<vector<int>>& mat, vector<vector<int>>& target) {
    bool ans = true;
    int n = mat.size();
    int m = mat[0].size();
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (mat[i][j] != target[i][j]) ans = false;
      }
    }
    return ans;
  }

 public:
  bool findRotation(vector<vector<int>>& mat, vector<vector<int>>& target) {
    bool ans = check(mat, target);
    if (ans) {
      return ans;
    }

    for (int i = 0; i < 4; i++) {
      rotate(mat);
      bool ans = check(mat, target);
      if (ans) {
        return ans;
      }
    }
    return false;
  }
};

class Solution {
 public:
  int minFlips(string s) {
    int n = s.length();
    s = s + s;
    int m = s.length();
    vector<int> s1(m, 0);
    vector<int> s2(m, 0);
    int cnt1 = 0;
    for (int i = 0; i < m; i++) {
      if (i % 2 == 0) {
        if (s[i] != '0') {
          s1[i] = 1;
        }

      } else {
        if (s[i] != '1') {
          s1[i] = 1;
        }
      }
    }
    int cnt2 = 0;
    for (int i = 0; i < m; i++) {
      if (i % 2 == 0) {
        if (s[i] != '1') {
          s2[i] = 1;
        }
      } else {
        if (s[i] != '0') {
          s2[i] = 1;
        }
      }
    }
    for (int i = 0; i < n; i++) {
      cnt1 += s1[i];
      cnt2 += s2[i];
    }
    int min12 = min(cnt1, cnt2);
    for (int i = n; i < m; i++) {
      cnt1 += s1[i];
      cnt1 -= s1[i - n];
      cnt2 += s2[i];
      cnt2 -= s2[i - n];
      min12 = min(min12, min(cnt1, cnt2));
    }
    return min12;
  }
};

class Solution {
 public:
  bool sumGame(string num) {
    int left = 0, right = 0, leftQ = 0, rightQ = 0;
    int n = num.size();
    for (int i = 0; i < n / 2; i++) {
      if (num[i] == '?') {
        leftQ++;
      } else {
        left += num[i] - '0';
      }
    }
    for (int i = n / 2; i < n; i++) {
      if (num[i] == '?') {
        rightQ++;
      } else {
        right += num[i] - '0';
      }
    }
    if ((leftQ + rightQ) % 2 == 1) return true;
    return left - right != (rightQ - leftQ) * 9 / 2;
  }
};

class Solution {
 public:
  vector<vector<int>> rotateGrid(vector<vector<int>>& grid, int k) {
    int m = grid.size();
    int n = grid[0].size();

    int layers = min(m, n) / 2;  // each layer require two rows and two columns

    for (int layer = 0; layer < layers; layer++) {
      vector<int> nums;

      int top = layer;
      int bottom = m - layer - 1;
      int left = layer;
      int right = n - layer - 1;

      // Top row (left -> right)
      for (int j = left; j <= right; j++) {
        nums.push_back(grid[top][j]);
      }

      // Right column (top -> bottom)
      // Skip corners because they are already included in top/bottom rows
      for (int i = top + 1; i <= bottom - 1; i++) {
        nums.push_back(grid[i][right]);
      }

      // Bottom row (right -> left)
      for (int j = right; j >= left; j--) {
        nums.push_back(grid[bottom][j]);
      }

      // Left column (bottom -> top)
      // Skip corners because they are already included in top/bottom rows
      for (int i = bottom - 1; i >= top + 1; i--) {
        nums.push_back(grid[i][left]);
      }

      int len = nums.size();

      int nomralized_k = k % len;

      rotate(begin(nums), begin(nums) + nomralized_k, end(nums));

      int idx = 0;

      for (int j = left; j <= right; j++) {
        grid[top][j] = nums[idx++];
      }

      for (int i = top + 1; i <= bottom - 1; i++) {
        grid[i][right] = nums[idx++];
      }

      for (int j = right; j >= left; j--) {
        grid[bottom][j] = nums[idx++];
      }

      for (int i = bottom - 1; i >= top + 1; i--) {
        grid[i][left] = nums[idx++];
      }
    }

    return grid;
  }
};

class Solution {
 public:
  vector<vector<long long>> splitPainting(vector<vector<int>>& segments) {
    map<int, long long> event;
    for (auto& s : segments) {
      event[s[0]] += s[2];
      event[s[1]] -= s[2];
    }
    auto it = event.begin();
    long long sum = it->second;
    int start = it->first;
    it++;
    vector<vector<long long>> ans;
    for (; it != event.end(); it++) {
      if (sum > 0) ans.push_back({start, it->first, sum});
      sum += it->second;
      start = it->first;
    }
    return ans;
  }
};

