class Solution {
 public:
  long long maxMatrixSum(vector<vector<int>>& matrix) {
    long long sum = 0;
    int minAbs = INT_MAX;
    int negCount = 0;

    for (auto& row : matrix) {
      for (int x : row) {
        if (x < 0) negCount++;
        sum += abs(x);
        minAbs = min(minAbs, abs(x));
      }
    }

    if (negCount % 2 == 1) {
      sum -= 2LL * minAbs;
    }

    return sum;
  }
};

