class Solution {
  bool bfs(vector<vector<int>>& world) {
    int row = world.size();
    int col = world[0].size();

    queue<pair<int, int>> q;
    vector<vector<bool>> vis(row, vector<bool>(col, false));

    for (int j = 0; j < col; j++) {
      if (world[0][j] == 1) {
        q.push({0, j});
        vis[0][j] = true;
      }
    }

    int dir[4][2] = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    while (!q.empty()) {
      auto [r, c] = q.front();
      q.pop();

      if (r == row - 1) return true;

      for (auto& d : dir) {
        int nr = r + d[0];
        int nc = c + d[1];

        if (nr >= 0 && nr < row && nc >= 0 && nc < col && !vis[nr][nc] &&
            world[nr][nc] == 1) {
          vis[nr][nc] = true;
          q.push({nr, nc});
        }
      }
    }
    return false;
  }

  bool check(int day, int row, int col, vector<vector<int>>& cells) {
    vector<vector<int>> world(row, vector<int>(col, 1));

    for (int i = 0; i < day; i++) {
      int x = cells[i][0] - 1;
      int y = cells[i][1] - 1;
      world[x][y] = 0;
    }

    return bfs(world);
  }

 public:
  int latestDayToCross(int row, int col, vector<vector<int>>& cells) {
    int left = 0;
    int right = cells.size();
    int ans = 0;

    while (left <= right) {
      int mid = left + (right - left) / 2;

      if (check(mid, row, col, cells)) {
        ans = mid;
        left = mid + 1;
      } else {
        right = mid - 1;
      }
    }
    return ans;
  }
};

class LockingTree {
  unordered_map<int, int> islock;
  vector<int> parent;
  vector<vector<int>> adj;
  void unlockChild(int num) {
    islock[num] = -1;
    for (auto v : adj[num]) {
      unlockChild(v);
    }
    return;
  }
  bool parentCheck(int num) {
    if (islock[num] != -1) {
      return false;
    }
    if (parent[num] == -1) {
      return true;
    }
    return parentCheck(parent[num]);
  }
  bool childCheck(int num) {
    if (islock[num] != -1) {
      return true;
    }
    bool ans = false;
    for (auto v : adj[num]) {
      ans |= childCheck(v);
    }
    return ans;
  }

 public:
  LockingTree(vector<int>& parent) {
    this->parent = parent;
    int n = parent.size();
    adj.resize(n);
    for (int i = 1; i < n; i++) {
      adj[parent[i]].push_back(i);
    }
    for (int i = 0; i < n; i++) {
      islock[i] = -1;
    }
  }

  bool lock(int num, int user) {
    if (islock[num] != -1) {
      return false;
    }
    islock[num] = user;
    return true;
  }

  bool unlock(int num, int user) {
    if (islock[num] == user) {
      islock[num] = -1;
      return true;
    }
    return false;
  }

  bool upgrade(int num, int user) {
    if (islock[num] == -1) {
      if (parentCheck(num)) {
        if (childCheck(num)) {
          unlockChild(num);
          islock[num] = user;
          return true;
        }
      }
    }
    return false;
  }
};

