/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
 public:
  vector<int> nodesBetweenCriticalPoints(ListNode* head) {
    ListNode* curr = head;
    ListNode* prev = NULL;
    int minDistance = 1e9, maxDistance = 0;
    int idx = -1;
    int i = 1;
    int sidx = -1;
    while (curr != NULL && curr->next != NULL) {
      if (prev != NULL &&
          ((curr->val > prev->val && curr->val > curr->next->val) ||
           (curr->val < prev->val && curr->val < curr->next->val))) {
        if (idx == -1) {
          idx = i;
          sidx = i;
        } else {
          minDistance = min(minDistance, i - idx);
          idx = i;
        }
      }
      i++;
      prev = curr;
      curr = curr->next;
    }
    if (sidx != -1) maxDistance = idx - sidx;
    return {minDistance == 1e9 ? -1 : minDistance,
            maxDistance == 0 ? -1 : maxDistance};
  }
};

class Solution {
 public:
  string decodeCiphertext(string encodedText, int rows) {
    int col = encodedText.size() / rows;
    vector<vector<char>> vc(rows, vector<char>(col));
    for (int i = 0; i < rows; i++) {
      for (int j = 0; j < col; j++) {
        vc[i][j] = encodedText[(i * col) + j];
      }
    }
    string s;

    for (int stc = 0; stc < col; stc++) {
      int i = 0, j = stc;
      while (i < rows && j < col) {
        s.push_back(vc[i][j]);
        i++;
        j++;
      }
    }
    int n = s.length();
    int i;
    for (i = n - 1; i >= 0; i--) {
      if (s[i] != ' ') break;
    }
    s.erase(s.begin() + i + 1, s.end());
    return s;
  }
};

