class Solution {
 public:
  int minimumDeletions(vector<int>& nums) {
    int n = nums.size();
    if (n == 1) return 1;
    int smallIdx = min_element(nums.begin(), nums.end()) - nums.begin();
    int largeIdx = max_element(nums.begin(), nums.end()) - nums.begin();
    int front = max(smallIdx + 1, largeIdx + 1);
    int last = max(n - smallIdx, n - largeIdx);
    int both = min(smallIdx + 1 + n - largeIdx, largeIdx + 1 + n - smallIdx);
    return min({front, last, both});
  }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
  ListNode* findMid(ListNode* head) {
    ListNode* slow = head;
    ListNode* fast = head;
    while (fast != NULL && fast->next != NULL) {
      fast = fast->next->next;
      slow = slow->next;
    }
    return slow;
  }
  ListNode* reverse(ListNode* head) {
    ListNode* curr = head;
    ListNode* prev = NULL;
    ListNode* next = NULL;

    while (curr != NULL) {
      next = curr->next;
      curr->next = prev;
      prev = curr;
      curr = next;
    }
    return prev;
  }

 public:
  int pairSum(ListNode* head) {
    ListNode* curr = head;
    ListNode* mid = findMid(head);
    ListNode* tail = reverse(mid);
    int sum = 0;
    int maxSum = 0;
    while (tail != NULL) {
      sum = curr->val + tail->val;
      maxSum = max(sum, maxSum);
      curr = curr->next;
      tail = tail->next;
    }
    return maxSum;
  }
};

