class Solution {
 public:
  string shiftingLetters(string s, vector<vector<int>>& shifts) {
    int n = s.size();
    vector<int> ans(n);
    for (auto& sh : shifts) {
      int start = sh[0];
      int end = sh[1];
      int d = sh[2];
      if (d == 0) {
        ans[start] -= 1;
        if (end + 1 < n) ans[end + 1] += 1;
      } else if (d == 1) {
        ans[start] += 1;
        if (end + 1 < n) ans[end + 1] -= 1;
      }
    }
    int sum = 0;
    for (int i = 0; i < n; i++) {
      sum += ans[i];
      ans[i] = sum;
    }
    int shift = 0;
    for (int i = 0; i < n; i++) {
      int c = s[i] - 'a';
      shift = (c + ans[i]);
      shift %= 26;
      if (shift < 0) shift += 26;
      s[i] = shift + 'a';
    }
    return s;
  }
};

class DSU {
  vector<int> parent;
  vector<long long> sum;
  vector<bool> vis;
  int n;

 public:
  long long maxe = 0;
  DSU(int n) {
    this->n = n;
    parent.resize(n);
    sum.resize(n);
    vis.assign(n, false);
    for (int i = 0; i < n; i++) {
      parent[i] = i;
    }
  }
  int find(int u) {
    if (parent[u] == u) {
      return u;
    }
    return parent[u] = find(parent[u]);
  }
  void insert(int u, int v) {
    vis[u] = true;
    sum[u] = v;
    if (u + 1 < n && vis[u + 1]) {
      int a = find(u);
      ;
      int b = find(u + 1);
      if (a != b) {
        parent[a] = b;
        sum[b] += sum[a];
      }
    }
    if (u - 1 >= 0 && vis[u - 1]) {
      int a = find(u);
      int b = find(u - 1);
      if (a != b) {
        parent[a] = b;
        sum[b] += sum[a];
      }
    }
    maxe = max(maxe, sum[find(u)]);
  }
};

