class Solution {
 public:
  vector<int> survivedRobotsHealths(vector<int>& positions,
                                    vector<int>& healths, string directions) {
    int n = positions.size();
    vector<int> ai(n);
    for (int i = 0; i < n; i++) {
      ai[i] = i;
    }
    auto lamda = [&](int& i, int& j) { return positions[i] < positions[j]; };
    sort(ai.begin(), ai.end(), lamda);
    vector<int> result;
    stack<int> st;
    for (auto curr : ai) {
      if (directions[curr] == 'R') {
        st.push(curr);
      } else {
        while (!st.empty() && healths[curr] > 0) {
          int top = st.top();
          st.pop();
          if (healths[top] > healths[curr]) {
            healths[top] -= 1;
            healths[curr] = 0;
            st.push(top);
          } else if (healths[top] < healths[curr]) {
            healths[top] = 0;
            healths[curr] -= 1;
          } else {
            healths[top] = 0;
            healths[curr] = 0;
          }
        }
      }
    }
    for (int i = 0; i < n; i++) {
      if (healths[i] > 0) {
        result.push_back(healths[i]);
      }
    }
    return result;
  }
};

class Solution {
  int n;
  int rec(int i, vector<int>& nums, int target, vector<int>& dp) {
    if (i == n - 1) {
      return 0;
    }
    if (dp[i] != -1) {
      return dp[i];
    }
    int ans = -1e9;
    for (int j = i + 1; j < n; j++) {
      if (abs(nums[j] - nums[i]) <= target) {
        ans = max(ans, 1 + rec(j, nums, target, dp));
      }
    }
    return dp[i] = (ans < 0) ? -1e9 : ans;
  }

 public:
  int maximumJumps(vector<int>& nums, int target) {
    n = nums.size();
    vector<int> dp(n, -1e9);
    dp[n - 1] = 0;

    for (int i = n - 2; i >= 0; i--) {
      int a = -1e9;
      for (int j = i + 1; j < n; j++) {
        if (abs(nums[j] - nums[i]) <= target && dp[j] != -1e9) {
          a = max(a, 1 + dp[j]);
        }
      }
      dp[i] = a;
    }
    int ans = dp[0];
    return (ans < 0) ? -1 : ans;
  }
};

