    for (auto num : nums) {
      for (int i = 0; i < 32; i++) {
        if (num & (1 << i)) {
          cnt[i]++;
        }
      }
    }
    while (k--) {
      long long cur = 0;
      for (int i = 0; i < 32; i++) {
        if (cnt[i] > 0) {
