    k %= m;
    for (int i = 0; i < n; i++) {
      if (i % 2 == 0) {
        for (int j = 0; j < m; j++) {
          int ni = (j - k + m) % m;
          ma[i][ni] = mat[i][j];
        }
      } else {
        for (int j = 0; j < m; j++) {
          int ni = (j + k) % m;
          ma[i][ni] = mat[i][j];
        }
      }
    }
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (mat[i][j] != ma[i][j]) {
          return false;
        }
      }
    }
    return true;
  }
};

class Solution {
 public:
  vector<int> lexicographicallySmallestArray(vector<int>& nums, int limit) {
    vector<int> vec = nums;
    // sort the vec
    sort(begin(vec), end(vec));
    int grp = 0;
    unordered_map<int, int> noToGroup;
    unordered_map<int, deque<int>> groupToNo;
    noToGroup[vec[0]] = grp;
    groupToNo[grp].push_back(vec[0]);
    int n = nums.size();
    for (int i = 1; i < n; i++) {
      if (abs(vec[i] - vec[i - 1]) > limit) {
        grp++;
      }
      noToGroup[vec[i]] = grp;
      groupToNo[grp].push_back(vec[i]);
    }
    // build the ans -merge the group
    vector<int> ans(n);
    for (int i = 0; i < n; i++) {
      int num = nums[i];
      int grp = noToGroup[num];
      // smallest awailable no in this group
      ans[i] = groupToNo[grp].front();  // use ho gaya delete element
      groupToNo[grp].pop_front();
    }
    return ans;
  }
};

class Solution {
 public:
  int maxSubarrayLength(vector<int>& nums, int k) {
    int i = 0, j = 0;
    int n = nums.size();
    unordered_map<int, int> mp;
    int ans = 0;
    while (j < n) {
      mp[nums[j]]++;
      while (mp[nums[j]] > k) {
        mp[nums[i]]--;
        i++;
      }
      j++;
      ans = max(ans, j - i);
    }
    return ans;
  }
};

