class Solution {
 public:
  const long long INF = 1e18;

  unordered_map<string, int> mp;
  vector<vector<long long>> dist;
  string src, tgt;
  int n;
  vector<long long> dp;

  long long solve(int i) {
    if (i == n) return 0;
    if (dp[i] != -1) return dp[i];

    long long ans = INF;  // make ans INF so that when done min later it reduces

    // Option 1: characters already match
    if (src[i] == tgt[i]) {
      ans = min(ans, solve(i + 1));
    }

    // Option 2: try all substring replacements

    for (auto &p1 : mp) {
      // check for valid source substring s1
      const string &s1 = p1.first;
      int u = p1.second;
      int len = s1.size();

      if (i + len > n) continue;
      if (src.compare(i, len, s1) != 0) continue;

      for (auto &p2 : mp) {
        // find a valid target substring s2
        const string &s2 = p2.first;
        int v = p2.second;

        if (tgt.compare(i, len, s2) != 0) continue;
        if (dist[u][v] == INF) continue;

        ans = min(ans, dist[u][v] + solve(i + len));
      }
    }

    return dp[i] = ans;
  }

  long long minimumCost(string source, string target, vector<string> &original,
                        vector<string> &changed, vector<int> &cost) {
    src = source;
    tgt = target;
    n = source.size();

    // Map all unique strings and for each string -> Link it with a unique ID
    int cnt = 0;
    for (int i = 0; i < original.size(); i++) {
      if (!mp.count(original[i])) mp[original[i]] = cnt++;
      if (!mp.count(changed[i])) mp[changed[i]] = cnt++;
    }

    // Build distance matrix cnt*cnt
    dist.assign(cnt, vector<long long>(cnt, INF));

    for (int i = 0; i < cnt; i++) dist[i][i] = 0;

    for (int i = 0; i < original.size(); i++) {
      int u = mp[original[i]];
      int v = mp[changed[i]];
      dist[u][v] = min(dist[u][v], (long long)cost[i]);
    }

    // Floyd–Warshall
    for (int k = 0; k < cnt; k++)
      for (int i = 0; i < cnt; i++)
        for (int j = 0; j < cnt; j++)
          dist[i][j] = min(dist[i][j], dist[i][k] + dist[k][j]);

    // Memoized DFS
    dp.assign(n, -1);
    long long ans = solve(0);

    if (ans >= INF) return -1;

    return ans;
  }
};

class Solution {
 public:
  int maximizeSquareArea(int m, int n, vector<int>& hFences,
                         vector<int>& vFences) {
    vector<int> h(hFences.begin(), hFences.end());
    vector<int> v(vFences.begin(), vFences.end());
    h.insert(h.begin(), 1);
    v.insert(v.begin(), 1);
    h.push_back(m);
    v.push_back(n);
    unordered_set<int> s;
    for (int i = 0; i < h.size(); i++) {
      for (int j = i + 1; j < h.size(); j++) {
        s.insert(abs(h[i] - h[j]));
      }
    }
    int maxSide = 0;
    for (int i = 0; i < v.size(); i++) {
      for (int j = i + 1; j < v.size(); j++) {
        if (s.contains(abs(v[i] - v[j])))
          maxSide = max(abs(v[i] - v[j]), maxSide);
      }
    }
    if (maxSide == 0) {
      return -1;
    } else
      return (1LL * maxSide * maxSide) % 1000000007;
  }
};

class Solution {
 public:
  struct SmartWindow {
    int K;
    multiset<int> low, high;
    long long sumLow = 0;

    SmartWindow(int k) : K(k) {}

    int windowSize() const { return (int)low.size() + (int)high.size(); }
    void rebalance() {
      int need = min(K, windowSize());

      while ((int)low.size() > need) {
        auto it = prev(low.end());
        int x = *it;
        low.erase(it);
        sumLow -= x;
        high.insert(x);
      }
      while ((int)low.size() < need && !high.empty()) {
        auto it = high.begin();
        int x = *it;
        high.erase(it);
        low.insert(x);
        sumLow += x;
      }
    }
    void add(int x) {
      if (low.empty() || x <= *prev(low.end())) {
        low.insert(x);
        sumLow += x;
      } else {
        high.insert(x);
      }
      rebalance();
    }
    void remove(int x) {
      auto itLow = low.find(x);
      if (itLow != low.end()) {
        low.erase(itLow);
        sumLow -= x;
      } else {
        auto itHigh = high.find(x);
        if (itHigh != high.end()) {
          high.erase(itHigh);
        }
      }
      rebalance();
    }
    long long query() const { return sumLow; }
  };
  long long minimumCost(vector<int>& nums, int k, int dist) {
    int n = (int)nums.size();
    k -= 1;
    SmartWindow window(k);
    for (int i = 1; i <= 1 + dist; i++) {
      window.add(nums[i]);
    }
    long long ans = window.query();
    for (int i = 2; i + dist < n; i++) {
      window.remove(nums[i - 1]);
      window.add(nums[i + dist]);
      ans = min(ans, window.query());
    }
    return ans + nums[0];
  }
};

