class Solution {
  using ll = long long;
  vector<int> coins;
  ll getCnt(ll x) {
    int size = coins.size();
    int n = (1 << size) - 1;  // all ones=2^size-1
    ll cnt = 0;
    for (int i = 1; i <= n; i++) {  // from i=mask 1 to all ones
      ll setBitsLcm = 1;
      for (int j = 0; j < size; j++) {
        if (i & (1 << j)) {
          setBitsLcm = lcm(setBitsLcm, coins[j]);
        }
      }
      if (__builtin_popcount(i) & 1) {  // get count of set bits
        cnt += x / setBitsLcm;
      } else {
        cnt -= x / setBitsLcm;
      }
    }
    return cnt;
  }

 public:
  long long findKthSmallest(vector<int>& coins, int k) {
    this->coins = coins;
    ll l = 1, r = 25 * 2 * 1e9 + 25, ans = 0;
    while (l <= r) {
      ll x = l + (r - l) / 2;
      ll cnt = getCnt(x);
      if (cnt < k) {
        l = x + 1;
      } else {
        ans = x;
        r = x - 1;
      }
    }
    return ans;
  }
};

struct Trie {
  int idx;
  Trie* child[26];
  ~Trie() {
    for (int i = 0; i < 26; i++) {
      delete child[i];
    }
  }
};

Trie* getNode(int i) {
  Trie* temp = new Trie();
  temp->idx = i;
  for (int i = 0; i < 26; i++) {
    temp->child[i] = NULL;
  }
  return temp;
}

void insert(Trie* root, int i, vector<string>& wordsContainer) {
  string word = wordsContainer[i];
  int n = word.size();
  for (int j = n - 1; j >= 0; j--) {
    char ch = word[j];
    int idx = ch - 'a';
    if (root->child[idx] == NULL) {
      root->child[idx] = getNode(i);
    }
    root = root->child[idx];
    if (wordsContainer[root->idx].size() > n) {
      root->idx = i;
    }
  }
}
int search(Trie* root, string& word) {
  int result_idx = root->idx;
  int n = word.length();
  for (int i = n - 1; i >= 0; i--) {
    int idx = word[i] - 'a';
    root = root->child[idx];
    if (root == NULL) {
      return result_idx;
    }
    result_idx = root->idx;
  }
  return result_idx;
}

class Solution {
 public:
  vector<int> stringIndices(vector<string>& wordsContainer,
                            vector<string>& wordsQuery) {
    int m = wordsContainer.size();
    int n = wordsQuery.size();
    vector<int> ans(n);
    Trie* root = getNode(0);
    for (int i = 0; i < m; i++) {
      int idx = root->idx;
      if (wordsContainer[i].size() < wordsContainer[idx].size()) {
        root->idx = i;
      }
      insert(root, i, wordsContainer);
    }
    for (int i = 0; i < n; i++) {
      ans[i] = search(root, wordsQuery[i]);
    }
    delete root;
    return ans;
  }
};

