class Solution {
 public:
  const int MOD = 1000000007;

  int numberOfStableArrays(int zero, int one, int limit) {
    vector<vector<long long>> dp0(zero + 1, vector<long long>(one + 1, 0));
    vector<vector<long long>> dp1(zero + 1, vector<long long>(one + 1, 0));

    for (int z = 1; z <= min(zero, limit); z++) dp0[z][0] = 1;

    for (int o = 1; o <= min(one, limit); o++) dp1[0][o] = 1;

    for (int z = 0; z <= zero; z++) {
      for (int o = 0; o <= one; o++) {
        for (int k = 1; k <= limit && k <= z; k++) {
          dp0[z][o] = (dp0[z][o] + dp1[z - k][o]) % MOD;
        }

        for (int k = 1; k <= limit && k <= o; k++) {
          dp1[z][o] = (dp1[z][o] + dp0[z][o - k]) % MOD;
        }
      }
    }

    return (dp0[zero][one] + dp1[zero][one]) % MOD;
  }
};

class Solution {
 public:
  int numberOfStableArrays(int zero, int one, int limit) {
    const int MOD = 1e9 + 7;
    vector<vector<array<long, 2>>> dp(
        zero + 1, vector<array<long, 2>>(one + 1, {0LL, 0LL}));

    for (int i = 1; i <= min(zero, limit); i++) dp[i][0][0] = 1;
    for (int j = 1; j <= min(one, limit); j++) dp[0][j][1] = 1;

    for (int i = 1; i <= zero; i++) {
      for (int j = 1; j <= one; j++) {
        long over0 = (i - limit >= 1) ? dp[i - limit - 1][j][1] : 0;
        long over1 = (j - limit >= 1) ? dp[i][j - limit - 1][0] : 0;
        dp[i][j][0] = (dp[i - 1][j][0] + dp[i - 1][j][1] - over0 + MOD) % MOD;
        dp[i][j][1] = (dp[i][j - 1][0] + dp[i][j - 1][1] - over1 + MOD) % MOD;
      }
    }
    return (dp[zero][one][0] + dp[zero][one][1]) % MOD;
  }
};

