    for (auto& p : count) {
      vec.push_back(p);
    }
    int n = vec.size();
    vector<long long> f(n, 0);
    long long mx = 0;
    for (int i = 1, j = 1; i < n; i++) {
      while (j < i && vec[j].first < vec[i].first - 2) {
        mx = max(mx, f[j]);
        j++;
