 public:
  long long maximumScore(vector<vector<int>>& grid) {
    int n = grid.size();
    int m = grid[0].size();
    if (m == 1) return 0;

    // prefix sum for each column
    vector<vector<long long>> col(m, vector<long long>(n + 1, 0));
    for (int j = 0; j < m; j++) {
      for (int i = 0; i < n; i++) {
        col[j][i + 1] = col[j][i] + grid[i][j];
      }
    }

    // dp[curr][prev]
    vector<vector<long long>> dp(n + 1, vector<long long>(n + 1, 0));
    vector<vector<long long>> prefMax(n + 1, vector<long long>(n + 1, 0));
    vector<vector<long long>> suffMax(n + 1, vector<long long>(n + 1, 0));

    for (int c = 1; c < m; c++) {
      vector<vector<long long>> newdp(n + 1, vector<long long>(n + 1, 0));

      for (int curr = 0; curr <= n; curr++) {
        for (int prev = 0; prev <= n; prev++) {
          if (curr <= prev) {
            long long gain = col[c][prev] - col[c][curr];

            newdp[curr][prev] = max(newdp[curr][prev], suffMax[prev][0] + gain);
          } else {
            long long gain = col[c - 1][curr] - col[c - 1][prev];

            newdp[curr][prev] = max({newdp[curr][prev], suffMax[prev][curr],
                                     prefMax[prev][curr] + gain});
          }
        }
      }

      // build prefix max & suffix max
      for (int curr = 0; curr <= n; curr++) {
        prefMax[curr][0] = newdp[curr][0];

        for (int prev = 1; prev <= n; prev++) {
          long long penalty = 0;
          if (prev > curr) penalty = col[c][prev] - col[c][curr];

          prefMax[curr][prev] =
              max(prefMax[curr][prev - 1], newdp[curr][prev] - penalty);
        }

        suffMax[curr][n] = newdp[curr][n];

        for (int prev = n - 1; prev >= 0; prev--) {
          suffMax[curr][prev] = max(suffMax[curr][prev + 1], newdp[curr][prev]);
        }
      }

      dp = move(newdp);
    }

    long long ans = 0;
    for (int k = 0; k <= n; k++) {
      ans = max({ans, dp[0][k], dp[n][k]});
    }

    return ans;
  }
};

class Solution {
 public:
  int numberOfSubmatrices(vector<vector<char>>& grid) {
    int n = grid.size();
    int m = grid[0].size();

    // Prefix sum for X and Y
    vector<vector<int>> px(n, vector<int>(m, 0));
    vector<vector<int>> py(n, vector<int>(m, 0));

    // Build prefix sum
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        px[i][j] = (grid[i][j] == 'X');
        py[i][j] = (grid[i][j] == 'Y');

        if (i > 0) {
          px[i][j] += px[i - 1][j];
          py[i][j] += py[i - 1][j];
        }
        if (j > 0) {
          px[i][j] += px[i][j - 1];
          py[i][j] += py[i][j - 1];
        }
        if (i > 0 && j > 0) {
          px[i][j] -= px[i - 1][j - 1];
          py[i][j] -= py[i - 1][j - 1];
        }
      }
    }

    int ans = 0;

    // Check all submatrices from (0,0) to (i,j)
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (px[i][j] == py[i][j] && px[i][j] > 0) {
          ans++;
        }
      }
    }

    return ans;
  }
};

using ll = long long;
class Solution {
 public:
  ll minNumberOfSeconds(int height, vector<int>& times) {
    ll lo = 1, hi = 1e16;

    while (lo < hi) {
      ll mid = (lo + hi) >> 1;
      ll tot = 0;
      for (int i = 0; i < times.size() && tot < height; i++)
        tot += (ll)(sqrt((double)mid / times[i] * 2 + 0.25) - 0.5);
      if (tot >= height)
        hi = mid;
      else
        lo = mid + 1;
    }

    return lo;
  }
};

/**
 * Definition for singly-linked list.
 * struct ListNode {
 *     int val;
 *     ListNode *next;
 *     ListNode() : val(0), next(nullptr) {}
 *     ListNode(int x) : val(x), next(nullptr) {}
 *     ListNode(int x, ListNode *next) : val(x), next(next) {}
 * };
 */
class Solution {
 public:
  ListNode* modifiedList(vector<int>& nums, ListNode* head) {
    unordered_set<int> s(nums.begin(), nums.end());
    while (head && s.count(head->val)) {
      head = head->next;
    }
    ListNode* pre = head;
    ListNode* curr = head ? head->next : nullptr;

    while (curr != NULL) {
      if (s.count(curr->val)) {
        pre->next = curr->next;

      } else {
        pre = curr;
        ;
      }

      curr = curr->next;
    }
    return head;
  }
};

class Solution {
  vector<bool> vis;
  vector<bool> vis1;
  vector<vector<int>> adj;
  bool ok;
  void dfs(int u) {
    vis[u] = true;
    for (auto v : adj[u]) {
      if (!vis[v]) {
        dfs(v);
      }
    }
  }
  void okDFS(int u) {
    vis1[u] = true;
    for (auto v : adj[u]) {
      if (!vis1[v]) {
        if (!vis[v]) {
          okDFS(v);
        } else {
          ok = true;
          return;
        }
      }
    }
  }

 public:
  vector<int> remainingMethods(int n, int k, vector<vector<int>>& invocations) {
    ok = false;
    adj.resize(n);
    for (auto i : invocations) {
      adj[i[0]].push_back(i[1]);
    }
    vis.assign(n, false);
    vis1.assign(n, false);
    dfs(k);
    vector<int> ans;
    for (int i = 0; i < n; i++) {
      if (!vis[i]) {
        okDFS(i);
      }
    }
    if (ok) {
      ans.resize(n);
      iota(ans.begin(), ans.end(), 0);
      return ans;
    }
    for (int i = 0; i < n; i++) {
      if (!vis[i]) {
        ans.push_back(i);
      }
    }
    return ans;
  }
};

class Solution {
  struct Node {
    long long score = -1;
    vector<int> idx;
  };
  int n;
  vector<vector<int>> interval;
  vector<int> nextIdx;
  vector<vector<Node>> dp;
  int findNext(int i) {
    int l = 0, r = n - 1;
    int ans = n;
    while (l <= r) {
      int mid = l + (r - l) / 2;
      if (interval[mid][0] > i) {
        ans = mid;
        r = mid - 1;
      } else {
        l = mid + 1;
      }
    }
    return ans;
  }
  Node solve(int i, int k) {
    if (i >= n || k == 0) return Node();
    if (dp[i][k].score != -1) return dp[i][k];
    Node skip = solve(i + 1, k);
    int weight = interval[i][2];
    int idx = interval[i][3];
    int j = nextIdx[i];
    Node temp = solve(j, k - 1);
    Node take;
    take.score = temp.score + weight;
    take.idx = temp.idx;
    take.idx.push_back(idx);
    sort(take.idx.begin(), take.idx.end());
    Node ans;
    if (skip.score > take.score) {
      ans = skip;
    } else if (skip.score < take.score) {
      ans = take;
    } else {
      ans = (skip.idx < take.idx) ? skip : take;
    }
    return dp[i][k] = ans;
  }

 public:
  vector<int> maximumWeight(vector<vector<int>>& intervals) {
    interval = intervals;
    n = interval.size();
    nextIdx.resize(n);
    for (int i = 0; i < n; i++) {
      interval[i].push_back(i);
    }
    sort(interval.begin(), interval.end());
    for (int i = 0; i < n; i++) {
      int end = interval[i][1];
      nextIdx[i] = findNext(end);
    }
    int K = 4;
    dp.assign(n + 1, vector<Node>(K + 1));
    return solve(0, K).idx;
  }
};

class Solution {
 public:
  vector<int> gcdValues(vector<int>& nums, vector<long long>& queries) {
    int n = nums.size();
    int m = queries.size();
    int maxe = *max_element(begin(nums), end(nums));
    vector<int> freq(maxe + 1, 0);
    for (int i = 0; i < n; i++) {
      int num = nums[i];
      for (int j = 1; j * j <= num; j++) {
        if (num % j == 0) {
          freq[j]++;
          if (num / j != j) {
            freq[num / j]++;
          }
        }
      }
    }
    vector<long long> cnt(maxe + 1, 0);
    for (int g = maxe; g >= 1; g--) {
      long long count = freq[g];
      cnt[g] = (count * (count - 1)) / 2;
      for (int mul = 2 * g; mul <= maxe; mul += g) {
        cnt[g] -= cnt[mul];
      }
    }
    vector<long long> pref(maxe + 1, 0);
    for (int g = 1; g <= maxe; g++) {
      pref[g] = pref[g - 1] + cnt[g];
    }
    vector<int> ans;
    for (auto idx : queries) {
      int l = 1;
      int r = maxe;
      int temp = 1;
      while (l <= r) {
        int mid = (l + (r - l) / 2);
        if (pref[mid] > idx) {
          temp = mid;
          r = mid - 1;
        } else {
          l = mid + 1;
        }
      }
      ans.push_back(temp);
    }
    return ans;
  }
};

class Solution {
 public:
  vector<int> validSequence(string word1, string word2) {
    int n1 = word1.size(), n2 = word2.size();
    int i = n1 - 1, j = n2 - 1;
    vector<int> suffixMatchCnt(n1 + 1, 0);
    while (i >= 0) {
      suffixMatchCnt[i] = suffixMatchCnt[i + 1];
      if (j >= 0 && word1[i] == word2[j]) {
        suffixMatchCnt[i]++;
        j--;
      }
      i--;
    }
    vector<int> ans;
    i = 0, j = 0;
    bool canChange = true;
    while (i < n1 && j < n2) {
      if (word1[i] == word2[j]) {
        ans.push_back(i);
        j++;
      } else if (canChange && suffixMatchCnt[i + 1] >= n2 - j - 1) {
        ans.push_back(i);
        j++;
        canChange = false;
      }
      i++;
    }
    if (j == n2) return ans;
    return {};
  }
};

class Solution {
 public:
  vector<int> minBitwiseArray(vector<int>& nums) {
    vector<int> res;
    for (auto& n : nums) {
      if (n & 1) {
        auto z = ((n + 1) & ~n) >> 1;
        res.push_back(n & ~z);
      } else
        res.push_back(-1);
    }
    return res;
  }
};

