class Solution {
 public:
  bool hasIncreasingSubarrays(vector<int>& nums, int k) {
    int n = nums.size(), inc = 1, prevInc = 0, maxLen = 0;
    for (int i = 1; i < n; i++) {
      if (nums[i] > nums[i - 1])
        inc++;
      else {
        prevInc = inc;
        inc = 1;
      }
      maxLen = max(maxLen, max(inc >> 1, min(prevInc, inc)));
      if (maxLen >= k) return true;
    }
    return false;
  }
};

class Solution {
 public:
  int countValidSelections(vector<int>& nums) {
    int n = nums.size();
    int count = 0;
    vector<int> left(n, 0);
    vector<int> right(n, 0);

    for (int i = 1; i < n; i++) {
      left[i] = left[i - 1] + nums[i - 1];
      right[n - i - 1] = right[n - i] + nums[n - i];
    }

    for (int i = 0; i < n; i++) {
      if (nums[i] != 0) continue;
      if (left[i] == right[i])
        count += 2;
      else if (abs(left[i] - right[i]) == 1)
        count += 1;
    }

    return count;
  }
};

class Solution {
 public:
  int maxIncreasingSubarrays(vector<int>& nums) {
    int n = nums.size();
    int cnt = 1, precnt = 0, ans = 0;
    for (int i = 1; i < n; ++i) {
      if (nums[i] > nums[i - 1]) {
        ++cnt;
      } else {
        precnt = cnt;
        cnt = 1;
      }
      ans = max(ans, min(precnt, cnt));
      ans = max(ans, cnt / 2);
    }
    return ans;
  }
};

class Solution {
 public:
  int maxDistinctElements(vector<int>& nums, int k) {
    sort(nums.begin(), nums.end());
    int cnt = 0, prev = INT_MIN;
    for (int num : nums) {
      int curr = min(max(num - k, prev + 1), num + k);
      if (curr > prev) {
        cnt++;
        prev = curr;
      }
    }
    return cnt;
  }
};

class Solution {
 public:
  int maxFrequency(vector<int>& nums, int k, int numOperations) {
    int maxVal = *max_element(nums.begin(), nums.end()) + k + 2;

    vector<int> count(maxVal, 0);
    for (int v : nums) {
      count[v]++;
    }

    for (int i = 1; i < maxVal; i++) {
      count[i] += count[i - 1];
    }

    int res = 0;
    for (int i = 0; i < maxVal; i++) {
      int left = max(0, i - k);
      int right = min(maxVal - 1, i + k);
      int total = count[right] - (left ? count[left - 1] : 0);
      int freq = count[i] - (i ? count[i - 1] : 0);
      res = max(res, freq + min(numOperations, total - freq));
    }
    return res;
  }
};

class Solution {
 public:
  typedef long long ll;
  string freeSlotsFiller(ll required, int length) {
    string str;
    for (int digit = 9; digit >= 2; digit--) {
      while (required % digit == 0) {
        str.push_back(digit + '0');
        required /= digit;
      }
    }

    while (str.length() < length) {
      str.push_back('1');
    }

    reverse(begin(str), end(str));

    return str;
  }

  string smallestNumber(string num, long long t) {
    int n = num.length();

    ll temp = t;
    for (int primeFact : {2, 3, 5, 7}) {
      while (temp % primeFact == 0) {
        temp /= primeFact;
      }
    }

    if (temp != 1) {
      return "-1";
    }
    vector<ll> remainingFactor(n + 1, t);
    for (int i = 0; i < n; i++) {
      int digit = num[i] - '0';

      if (digit == 0) {
        break;
      }
      remainingFactor[i + 1] =
          remainingFactor[i] / gcd(remainingFactor[i], (ll)digit);
    }
    if (remainingFactor[n] == 1) {
      return num;
    }
    int zeroPos = num.find('0');
    int zeroIdx = n - 1;
    if (zeroPos != -1) {
      zeroIdx = zeroPos;
    }

    for (int i = zeroIdx; i >= 0; i--) {
      ll required = remainingFactor[i];
      int freeSlots = n - 1 - i;

      for (int digit = (num[i] - '0') + 1; digit <= 9; digit++) {
        ll furtherRequired = required / gcd(required, digit);
        string requiredNumber = freeSlotsFiller(furtherRequired, freeSlots);

        if (requiredNumber.length() == freeSlots) {
          return num.substr(0, i) + char(digit + '0') + requiredNumber;
        }
      }
    }

    return freeSlotsFiller(t, n + 1);
  }
};

class Solution {
 public:
  bool isZeroArray(vector<int>& nums, vector<vector<int>>& queries) {
    int n = nums.size();
    vector<int> diff(n);
    for (auto& q : queries) {
      int l = q[0];
      int r = q[1];
      diff[l] += 1;
      if (r + 1 < n) diff[r + 1] -= 1;
    }
    int sum = 0;
    for (int i = 0; i < n; i++) {
      sum += diff[i];
      nums[i] -= sum;
    }
    for (int i = 0; i < n; i++) {
      if (nums[i] > 0) {
        return false;
      }
    }
    return true;
  }
};

class Solution {
 public:
  int maxFrequency(vector<int>& nums, int k, int numOperations) {
    int n = nums.size();
    int maxe = *max_element(begin(nums), end(nums)) + k;
    map<int, int> diff;
    unordered_map<int, int> freq;
    for (int i = 0; i < n; i++) {
      int l = max(nums[i] - k, 0);
      int r = min(nums[i] + k, maxe);
      diff[l]++;
      diff[r + 1]--;
      diff[nums[i]] += 0;
      freq[nums[i]]++;
    }
    int ans = 0;
    int csum = 0;
    for (auto& [target, sum] : diff) {
      csum += sum;
      sum = csum;
      int targetFreq = freq[target];
      int need = csum - targetFreq;
      int maxPossible = min(need, numOperations);
      ans = max(ans, targetFreq + maxPossible);
    }
    return ans;
  }
};

class Solution {
  bool isValid(vector<int>& nums, vector<vector<int>>& q, int k) {
    int n = nums.size();
    vector<int> diff(n);
    for (int i = 0; i < k; i++) {
      int l = q[i][0];
      int r = q[i][1];
      int v = q[i][2];
      diff[l] += v;
      if (r + 1 < n) diff[r + 1] -= v;
    }
    int sum = 0;
    for (int i = 0; i < n; i++) {
      sum += diff[i];
      if (sum < nums[i]) {
        return false;
      }
    }
    return true;
  }

 public:
  int minZeroArray(vector<int>& nums, vector<vector<int>>& queries) {
    int n = queries.size();
    int l = 0, r = n;
    int ans = -1;
    while (l <= r) {
      int mid = l + (r - l) / 2;
      if (isValid(nums, queries, mid)) {
        ans = mid;
        r = mid - 1;
      } else {
        l = mid + 1;
      }
    }
    return ans;
  }
};

class Solution {
 public:
  int maxRemoval(vector<int>& nums, vector<vector<int>>& queries) {
    sort(queries.begin(), queries.end());
    priority_queue<int> available;
    priority_queue<int, vector<int>, greater<int>> assigned;
    int count = 0;

    for (int time = 0, k = 0; time < nums.size(); time++) {
      while (!assigned.empty() && assigned.top() < time) assigned.pop();
      while (k < queries.size() && queries[k][0] <= time)
        available.push(queries[k++][1]);
      while (assigned.size() < nums[time] && !available.empty() &&
             available.top() >= time) {
        assigned.push(available.top());
        available.pop();
        count++;
      }
      if (assigned.size() < nums[time]) return -1;
    }
    return queries.size() - count;
  }
};

class Solution {
