class Solution {
 public:
  int largestInteger(vector<int>& nums, int k) {
    int n = nums.size();
    map<int, int> freq;
    unordered_map<int, int> mp;
    int i = 0, j = 0;
    while (j < n) {
      while (j - i + 1 > k) {
        mp[nums[i]]--;
        i++;
      }
      mp[nums[j]]++;
      if (j - i + 1 == k) {
