class Solution {
 public:
  string generateString(string str1, string str2) {
    int n = str1.size();
    int m = str2.size();
    int len = n + m - 1;
    vector<bool> canChange(len, false);
    string str(len, '#');
    int i = 0;
    while (i < n) {
      if (str1[i] == 'T') {
        int j = 0;
        while (j < m) {
          if (str[i + j] == '#' || str[i + j] == str2[j]) {
            str[i + j] = str2[j];
          } else {
            return "";
          }

          j++;
        }
      }
      i++;
    }
    for (int i = 0; i < len; i++) {
      if (str[i] == '#') {
        canChange[i] = true;
        str[i] = 'a';
      }
    }
    i = 0;
    while (i < n) {
      if (str1[i] == 'F') {
        int j = 0;
        bool match = true;
        while (j < m) {
          if (str[i + j] != str2[j]) {
            match = false;

            break;
          }

          j++;
        }
        if (match) {
          bool changed = false;
          for (int j = m - 1; j >= 0; j--) {
            if (canChange[i + j]) {
              for (auto ch = 'a'; ch <= 'z'; ch++) {
                if (ch != str2[j]) {
                  str[i + j] = ch;
                  changed = true;
                  break;
                }
              }
            }
            if (changed) break;
          }
          if (!changed) return "";
        }
      }
      i++;
    }
    return str;
  }
};

class Solution {
 public:
  typedef long long ll;

  int minimumPairRemoval(vector<int>& nums) {
    int n = nums.size();

    //{a, b, c, d} --> {a, b+c, d}
    vector<ll> temp(n);
    for (int i = 0; i < n; i++) temp[i] = nums[i];

    set<pair<ll, int>> minPairSet;

    vector<int> nextIndex(n);
    vector<int> prevIndex(n);

    for (int i = 0; i < n; i++) {
      nextIndex[i] = i + 1;
      prevIndex[i] = i - 1;
    }

    int badPairs = 0;
    for (int i = 0; i < n - 1; i++) {
      if (temp[i] > temp[i + 1]) {
        badPairs++;
      }
      minPairSet.insert({temp[i] + temp[i + 1], i});
    }

    int operations = 0;

    while (badPairs > 0) {
      int first = minPairSet.begin()->second;
      int second = nextIndex[first];

      int first_left = prevIndex[first];
      int second_right = nextIndex[second];

      minPairSet.erase(begin(minPairSet));

      if (temp[first] > temp[second]) {
        badPairs--;
      }

      //{d, (a, b)}
      if (first_left >= 0) {
        if (temp[first_left] > temp[first] &&
            temp[first_left] <= temp[first] + temp[second]) {
          badPairs--;
        } else if (temp[first_left] <= temp[first] &&
                   temp[first_left] > temp[first] + temp[second]) {
          badPairs++;
        }
      }

      //{(a, b), d}
      if (second_right < n) {
        if (temp[second_right] >= temp[second] &&
            temp[second_right] < temp[first] + temp[second]) {
          badPairs++;
        } else if (temp[second_right] < temp[second] &&
                   temp[second_right] >= temp[first] + temp[second]) {
          badPairs--;
        }
      }

      if (first_left >= 0) {
        minPairSet.erase({temp[first_left] + temp[first], first_left});
        minPairSet.insert(
            {temp[first_left] + temp[first] + temp[second], first_left});
      }

      if (second_right < n) {
        minPairSet.erase({temp[second] + temp[second_right], second});
        minPairSet.insert(
            {temp[first] + temp[second] + temp[second_right], first});
        prevIndex[second_right] = first;
      }

      nextIndex[first] = second_right;
      temp[first] += temp[second];

      operations++;
    }

    return operations;
  }
};

class Solution {
 public:
  int minPair(vector<int> v) {
    int minSum = 1e9;
    int pos = -1;
    for (int i = 0; i < (int)v.size() - 1; i++) {
      if (v[i] + v[i + 1] < minSum) {
        minSum = v[i] + v[i + 1];
        pos = i;
      }
    }
    return pos;
  }
  void mergePair(vector<int>& v, int pos) {
    v[pos] += v[pos + 1];
    v.erase(v.begin() + pos + 1);
  }
  int minimumPairRemoval(vector<int>& nums) {
    int ops = 0;
    while (!is_sorted(nums.begin(), nums.end())) {
      mergePair(nums, minPair(nums));
      ops += 1;
    }
    return ops;
  }
};

