using namespace std;

class Solution {
 public:
  struct Event {
    long long y;
    int type;  // +1 add, -1 remove
    int l, r;  // compressed x indices
  };

  struct SegTree {
    int n;
    vector<int> cover;
    vector<long long> length;
    vector<long long> xs;

    SegTree(int n, vector<long long>& xs) : n(n), xs(xs) {
      cover.assign(4 * n, 0);
      length.assign(4 * n, 0);
    }

    void pushUp(int node, int l, int r) {
      if (cover[node] > 0) {
        length[node] = xs[r + 1] - xs[l];
      } else if (l == r) {
        length[node] = 0;
      } else {
        length[node] = length[node * 2] + length[node * 2 + 1];
      }
    }

    void update(int node, int l, int r, int ql, int qr, int val) {
      if (ql > r || qr < l) return;
      if (ql <= l && r <= qr) {
        cover[node] += val;
        pushUp(node, l, r);
        return;
      }
      int mid = (l + r) / 2;
      update(node * 2, l, mid, ql, qr, val);
      update(node * 2 + 1, mid + 1, r, ql, qr, val);
      pushUp(node, l, r);
    }

    long long query() { return length[1]; }
  };

  double separateSquares(vector<vector<int>>& squares) {
    vector<long long> xs;
    vector<Event> events;

    for (auto& s : squares) {
      long long x = s[0], y = s[1], l = s[2];
      xs.push_back(x);
      xs.push_back(x + l);
    }

    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());

    auto getX = [&](long long x) {
      return lower_bound(xs.begin(), xs.end(), x) - xs.begin();
    };

    for (auto& s : squares) {
      long long x = s[0], y = s[1], l = s[2];
      int L = getX(x);
      int R = getX(x + l) - 1;
      events.push_back({y, +1, L, R});
      events.push_back({y + l, -1, L, R});
    }

    sort(events.begin(), events.end(),
         [](auto& a, auto& b) { return a.y < b.y; });

    SegTree st(xs.size() - 1, xs);

    long long prevY = events[0].y;
    long double totalArea = 0;

    for (int i = 0; i < events.size();) {
      long long currY = events[i].y;
      long long width = st.query();
      totalArea += width * (currY - prevY);

      while (i < events.size() && events[i].y == currY) {
        st.update(1, 0, st.n - 1, events[i].l, events[i].r, events[i].type);
        i++;
      }
      prevY = currY;
    }

    long double target = totalArea / 2.0;
    long double currArea = 0;
    st = SegTree(xs.size() - 1, xs);
    prevY = events[0].y;

    for (int i = 0; i < events.size();) {
      long long currY = events[i].y;
      long long width = st.query();
      long double slabArea = width * (currY - prevY);

      if (currArea + slabArea >= target) {
        return (double)(prevY + (target - currArea) / width);
      }

      currArea += slabArea;

      while (i < events.size() && events[i].y == currY) {
        st.update(1, 0, st.n - 1, events[i].l, events[i].r, events[i].type);
        i++;
      }
      prevY = currY;
    }

    return (double)prevY;
  }
};

class Solution {
 public:
  int maxDistance(int side, vector<vector<int>>& points, int k) {
    vector<long long> res;
    for (auto& p : points) {
      int x = p[0], y = p[1];
      if (x == 0)
        res.push_back(y);
      else if (y == side)
        res.push_back((long long)side + x);
      else if (x == side)
        res.push_back((long long)side * 3 - y);
      else
        res.push_back((long long)side * 4 - x);
    }
    sort(res.begin(), res.end());

    auto check = [&](int n) {
      int m = res.size();
      vector<int> idx(k);
      long long curr = res[0];
      idx[0] = 0;
      for (int i = 1; i < k; i++) {
        auto it = lower_bound(res.begin(), res.end(), curr + n);
        if (it == res.end()) return false;
        idx[i] = distance(res.begin(), it);
        curr = *it;
      }
      if (res[idx[k - 1]] - res[0] <= (long long)side * 4 - n) return true;

      for (idx[0] = 1; idx[0] < idx[1]; idx[0]++) {
        for (int j = 1; j < k; j++) {
          while (idx[j] < m && res[idx[j]] < res[idx[j - 1]] + n) {
            idx[j]++;
          }
          if (idx[j] == m) return false;
        }
        if (res[idx[k - 1]] - res[idx[0]] <= (long long)side * 4 - n)
          return true;
      }
      return false;
    };

    int left = 1;
    int right = (1LL * side * 4) / k + 1;
    while (left + 1 < right) {
      int mid = left + (right - left) / 2;
      if (check(mid))
        left = mid;
      else
        right = mid;
    }
    return left;
  }
};

class Solution {
  int k;
  string s;
  vector<vector<vector<int>>> dp;
  int rec(int i, int j, int cost) {
    // cout<<i<<" "<<j<<" "<<cost<<endl;
    if (i == j) return 1;
    if (i > j) return 0;
    if (dp[i][j][cost] != -1) return dp[i][j][cost];
    int a = s[i] - 'a', b = s[j] - 'a';
    int diff = min(abs(b - a), 26 - abs(a - b));
    int take = 0;
    if (cost + diff <= k) take = 2 + rec(i + 1, j - 1, cost + diff);
    int notTake = max(rec(i, j - 1, cost), rec(i + 1, j, cost));
    return dp[i][j][cost] = max(take, notTake);
  }

 public:
  int longestPalindromicSubsequence(string s, int k) {
    this->s = s;
    this->k = k;
    int n = s.size();
    dp.assign(n, vector<vector<int>>(n, vector<int>(k + 1, -1)));
    return rec(0, n - 1, 0);
  }
};

class Solution {
