class Solution {
 public:
  string smallestPalindrome(string s) {
    int n = s.size();
    if (n < 2) {
      return s;
    }
    vector<int> cnt(26, 0);
    for (int i = 0; i < n; i++) {
      cnt[s[i] - 'a']++;
    }
    int mid = -1;
    string ans = "";
    for (int i = 0; i < 26; i++) {
      if (cnt[i] % 2 == 1) {
        mid = i;
      }
      if (cnt[i]) {
        cnt[i] /= 2;
      }
      while (cnt[i] > 0) {
        ans += ('a' + i);
        cnt[i]--;
      }
    }
    string a = ans;
    reverse(a.begin(), a.end());
    if (mid != -1) {
      ans += ('a' + mid);
    }
    ans += a;
    return ans;
  }
};

class Solution {
  long long ncr(int n, int r, int k) {
    r = min(r, n - r);
    long long ans = 1;
    for (int i = 1; i <= r; i++) {
      ans = ans * (n - r + i) / i;
      if (ans >= k) {
        return ans;
      }
    }
    return ans;
  }

 public:
  string smallestPalindrome(string s, int k) {
    int n = s.size();
    char mid = '\0';
    if (n % 2 == 1) {
      mid = s[n / 2];
    }
    vector<int> cnt(26, 0);
    for (int i = 0; i < n / 2; i++) {
      cnt[s[i] - 'a']++;
    }
    string half;

    for (int i = 0; i < n / 2; i++) {
      bool placed = false;
      for (int j = 0; j < 26; j++) {
        if (cnt[j] > 0) {
          cnt[j] -= 1;  // fixed the position
          long long ways = 1;
          int letter = 0;
          for (int i = 0; i < 26; i++) {
            letter += cnt[i];
          }
          for (int c = 0; c < 26; c++) {
            if (cnt[c] > 0) {
              ways *= ncr(letter, cnt[c], k);
              letter -= cnt[c];
            }
            if (ways >= k) break;
          }

          if (k <= ways) {
            half.push_back('a' + j);
            placed = true;
            break;
          } else {
            k = k - ways;
            cnt[j] += 1;
          }
        }
      }
      if (!placed) return "";
    }
    string rhalf = half;
    reverse(rhalf.begin(), rhalf.end());
    return half + (mid != '\0' ? string(1, mid) : "") + rhalf;
  }
};

class Solution {
 public:
  int uniqueXorTriplets(vector<int> &nums) {
    int n = nums.size();
    int maxe = *max_element(begin(nums), end(nums));
    int limit = 1;
    while (limit <= maxe) {
      limit *= 2;
    }
    vector<bool> one(limit, false);
    for (int num : nums) {
      one[num] = true;
    }
    vector<bool> two(limit, false);
    for (int i = 0; i < limit; i++) {
      if (one[i]) {
        for (int &num : nums) {
          two[i ^ num] = true;
        }
      }
    }
    vector<bool> three(limit, false);
    for (int i = 0; i < limit; i++) {
      if (two[i]) {
        for (int &num : nums) {
          three[i ^ num] = true;
        }
      }
    }
    int ans = 0;
    for (int i = 0; i < limit; i++) {
      if (three[i]) ans++;
    }
    return ans;
  }
};

class Solution {
  int msb(int n) {
    int ans = 0;
    while (n) {
      n >>= 1;
      ans++;
    }
    return ans;
  }

 public:
  int uniqueXorTriplets(vector<int>& nums) {
    int n = nums.size();
    if (n <= 2) {
      unordered_set<int> s;
      for (int i = 0; i < n; i++) {
        for (int j = i; j < n; j++) {
          for (int k = j; k < n; k++) {
            s.insert(nums[i] ^ nums[j] ^ nums[k]);
          }
        }
      }
      return s.size();
    }
    return pow(2, msb(n));
  }
};

class Solution {
 public:
  vector<long long> resultArray(vector<int>& nums, int k) {
    int n = nums.size();
    vector<long long> ans(k, 0);
    vector<long long> prev(k, 0);
    for (int i = 0; i < n; i++) {
      vector<long long> curr(k, 0);
      int currElement = nums[i] % k;
      curr[currElement]++;
      for (int old = 0; old < k; old++) {
        int newI = ((long long)old * (nums[i] % k)) % k;
        curr[newI] += prev[old];
      }
      prev = std::move(curr);
      for (int j = 0; j < k; j++) {
        ans[j] += prev[j];
      }
    }
    return ans;
  }
};

class DSU {
  vector<int> parent;
  vector<int> size;

 public:
  DSU(int n) {
    parent.resize(n);
    size.assign(n, 1);
    for (int i = 0; i < n; i++) {
      parent[i] = i;
    }
  }
  int find(int u) {
    if (parent[u] == u) {
      return u;
    }
    return parent[u] = find(parent[u]);
  }
  void uni(int u, int v) {
    u = find(u);
    v = find(v);
    if (u == v) return;
    if (size[u] < size[v]) {
      swap(u, v);
    }
    parent[v] = u;
    size[u] += size[v];
  }
};

class Solution {
 public:
  vector<bool> pathExistenceQueries(int n, vector<int>& nums, int maxDiff,
                                    vector<vector<int>>& queries) {
    DSU dsu(n);
    for (int i = 0; i < n - 1; i++) {
      if (abs(nums[i] - nums[i + 1]) <= maxDiff) {
        dsu.uni(i, i + 1);
      }
    }
    vector<bool> ans;
    for (auto& q : queries) {
      int u = q[0];
      int v = q[1];
      u = dsu.find(u);
      v = dsu.find(v);
      if (u == v) {
        ans.push_back(true);
      } else {
        ans.push_back(false);
      }
    }
    return ans;
  }
};

struct Node {
  int prod = 1;
  int cnt[5] = {0};
};
class Tree {
  vector<Node> segTree;
  vector<int> nums;
  int n, k;
  void build(int i, int left, int right) {
    if (left == right) {
      int curr = nums[left] % k;
      segTree[i].prod = curr;
      segTree[i].cnt[curr]++;
      return;
    }
    int mid = left + (right - left) / 2;
    build(2 * i + 1, left, mid);
    build(2 * i + 2, mid + 1, right);
    segTree[i] = merge(segTree[2 * i + 1], segTree[2 * i + 2]);
  }

 public:
  Tree(vector<int> &nums, int k) {
    this->nums = nums;
    this->k = k;
    n = nums.size();
    segTree.assign(4 * n, Node());
    build(0, 0, n - 1);
  }
  Node merge(Node &a, Node &b) {
    Node ans;
    ans.prod = (a.prod * b.prod) % k;
    for (int i = 0; i < 5; i++) {
      ans.cnt[i] = a.cnt[i];
    }
    for (int i = 0; i < 5; i++) {
      int newI = (a.prod * i) % k;
      ans.cnt[newI] += b.cnt[i];
    }
    return ans;
  }
  void update(int index, int val, int i, int l, int r) {
    if (l == r) {
      int oldcurr = nums[index] % k;
      nums[index] = val;
      int curr = nums[index] % k;
      segTree[i].prod = curr;
      segTree[i].cnt[oldcurr]--;
      segTree[i].cnt[curr]++;
      return;
    }
    int mid = l + (r - l) / 2;
    if (index <= mid) {
      update(index, val, 2 * i + 1, l, mid);
    } else {
      update(index, val, 2 * i + 2, mid + 1, r);
    }
    segTree[i] = merge(segTree[2 * i + 1], segTree[2 * i + 2]);
  }
  Node query(int i, int start, int end, int l, int r) {
    if (start > r || end < l) {
      return Node();
    }
    if (start <= l && end >= r) {
      return segTree[i];
    }
    int mid = l + (r - l) / 2;
    Node left = query(2 * i + 1, start, end, l, mid);
    Node right = query(2 * i + 2, start, end, mid + 1, r);
    return merge(left, right);
  }
};
class Solution {
 public:
  vector<int> resultArray(vector<int> &nums, int k,
                          vector<vector<int>> &queries) {
    int m = queries.size();
    int n = nums.size();
    vector<int> ans(m, 0);
    int j = 0;
    Tree t(nums, k);
    for (auto &q : queries) {
      int index = q[0];
      int val = q[1];
      int start = q[2];
      int x = q[3];
      t.update(index, val, 0, 0, n - 1);
      Node a = t.query(0, start, n - 1, 0, n - 1);
      ans[j] = a.cnt[x];
      j++;
    }
    return ans;
  }
};

class Solution {
  int dfs(unordered_map<int, vector<int>>& al, unordered_map<int, bool>& vis,
          int curr) {
    vis[curr] = true;

    int dept = 1;
    int maxdept = 1;
    for (auto l : al[curr]) {
      if (!vis[l]) {
        dept = 1 + dfs(al, vis, l);
        maxdept = max(maxdept, dept);
      }
    }

    return maxdept;
  }
  long long power(long long a, long long b) {
    long long mod = 1e9 + 7;
    long long res = 1;
    while (b) {
      if (b & 1) res = (res * a) % mod;
      a = (a * a) % mod;
      b >>= 1;
    }
    return res;
  }

 public:
  int assignEdgeWeights(vector<vector<int>>& edges) {
    int n = edges.size() + 1;

    unordered_map<int, vector<int>> al(n);
    for (auto& edge : edges) {
      int a = edge[0];
      int b = edge[1];
      al[a].push_back(b);
      al[b].push_back(a);
    }

    unordered_map<int, bool> vis;
    int mdept = dfs(al, vis, 1);
    long long ans = power(2, mdept - 2);
    return ans;
  }
};

