class Solution {
 public:
  bool canPartitionGrid(vector<vector<int>>& grid) {
    int n = grid.size();
    int m = grid[0].size();
    long long total = 0;
    for (auto& row : grid) {
      for (auto val : row) {
        total += val;
      }
    }
    long long curr = 0;
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        curr += grid[i][j];
      }
      if (curr * 2 == total) return true;
    }
    curr = 0;
    for (int j = 0; j < m; j++) {
      for (int i = 0; i < n; i++) {
        curr += grid[i][j];
      }
      if (curr * 2 == total) return true;
    }
    return false;
  }
};

class Solution {
 public:
  typedef long long ll;
  ll total = 0;

  bool checkHorCuts(vector<vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();

    unordered_set<ll> st;
    ll top = 0;

    for (int i = 0; i <= m - 2; i++) {
      for (int j = 0; j < n; j++) {
        st.insert(grid[i][j]);
        top += grid[i][j];
      }

      ll bottom = (total - top);
      ll diff = top - bottom;

      if (diff == 0) return true;
      if (diff == (ll)grid[0][0]) return true;
      if (diff == (ll)grid[0][n - 1]) return true;
      if (diff == (ll)grid[i][0]) return true;

      if (i > 0 && n > 1 && st.count(diff)) {
        return true;
      }
    }

    return false;
  }

  bool canPartitionGrid(vector<vector<int>>& grid) {
    int m = grid.size();
    int n = grid[0].size();

    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        total += grid[i][j];
      }
    }

    if (checkHorCuts(grid)) {
      return true;
    }

    reverse(begin(grid), end(grid));

    if (checkHorCuts(grid)) {
      return true;
    }

    reverse(begin(grid), end(grid));

    vector<vector<int>> transposeGrid(n, vector<int>(m));

    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        transposeGrid[j][i] = grid[i][j];
      }
    }

    if (checkHorCuts(transposeGrid)) {
      return true;
    }

    reverse(begin(transposeGrid), end(transposeGrid));

    if (checkHorCuts(transposeGrid)) {
      return true;
    }

    return false;
  }
};

class Solution {
  int rows;
  int col;
  vector<vector<int>> at;
  int cub(vector<pair<int, int>>& arr, int target) {
    int n = arr.size();
    int l = 0;
    int r = n - 1;
    int ans = 0;
    while (l <= r) {
      int mid = l + (r - l) / 2;
      if (arr[mid].first <= target) {
        l = mid + 1;
        ans = mid;
      } else {
        r = mid - 1;
      }
    }
    return ans;
  }

 public:
  vector<int> pathExistenceQueries(int n, vector<int>& nums, int maxDiff,
                                   vector<vector<int>>& queries) {
    vector<pair<int, int>> arr(n);
    for (int i = 0; i < n; i++) {
      arr[i] = {nums[i], i};
    }
    sort(arr.begin(), arr.end());
    vector<int> nodetoIdx(n);
    for (int i = 0; i < n; i++) {
      int node = arr[i].second;
      nodetoIdx[node] = i;
    }
    rows = n;
    col = log2(n) + 1;
    at.resize(rows, vector<int>(col, 0));
    for (int node = 0; node < n; node++) {
      int fioh = cub(arr, arr[node].first + maxDiff);
      at[node][0] = fioh;
    }
    for (int j = 1; j < col; j++) {
      for (int node = 0; node < rows; node++) {
        at[node][j] = at[at[node][j - 1]][j - 1];
      }
    }
    vector<int> ans;
    for (auto& q : queries) {
      int u = q[0];
      int v = q[1];
      int a = nodetoIdx[u];
      int b = nodetoIdx[v];
      if (a == b) {
        ans.push_back(0);
        continue;
      }
      if (a > b) {
        swap(a, b);
      }
      int curr = a;
      int jumps = 0;
      for (int j = col - 1; j >= 0; j--) {
        if (at[curr][j] < b) {
          curr = at[curr][j];
          jumps += (1 << j);
        }
      }
      if (at[curr][0] >= b) {
        ans.push_back(jumps + 1);
      } else {
        ans.push_back(-1);
      }
    }
    return ans;
  }
};

class Solution {
