class Vertex {
 public:
  int vertexId;
  bool offline = false;
  int powerGridId = -1;

  Vertex() {}
  Vertex(int id) : vertexId(id) {}
};

using PowerGrid = priority_queue<int, vector<int>, greater<int>>;
using Graph = vector<vector<int>>;

class Solution {
 private:
  vector<Vertex> vertices = vector<Vertex>();

  void traverse(Vertex& u, int powerGridId, PowerGrid& powerGrid,
                Graph& graph) {
    u.powerGridId = powerGridId;
    powerGrid.push(u.vertexId);
    for (int vid : graph[u.vertexId]) {
      Vertex& v = vertices[vid];
      if (v.powerGridId == -1) traverse(v, powerGridId, powerGrid, graph);
    }
  }

 public:
  vector<int> processQueries(int c, vector<vector<int>>& connections,
                             vector<vector<int>>& queries) {
    Graph graph(c + 1);
    vertices.resize(c + 1);

    for (int i = 1; i <= c; i++) {
      vertices[i] = Vertex(i);
    }

    for (auto& conn : connections) {
      graph[conn.at(0)].push_back(conn.at(1));
      graph[conn.at(1)].push_back(conn.at(0));
    }

    vector<PowerGrid> powerGrids;

    for (int i = 1, powerGridId = 0; i <= c; i++) {
      auto& v = vertices[i];
      if (v.powerGridId == -1) {
        PowerGrid powerGrid;
        traverse(v, powerGridId, powerGrid, graph);
        powerGrids.push_back(powerGrid);
        powerGridId++;
      }
    }

    vector<int> ans;
    for (auto& q : queries) {
      int op = q.at(0), x = q.at(1);
      if (op == 1) {
        if (!vertices[x].offline) {
          ans.push_back(x);
        } else {
          auto& powerGrid = powerGrids[vertices[x].powerGridId];
          while (!powerGrid.empty() && vertices[powerGrid.top()].offline) {
            powerGrid.pop();
          }
          ans.push_back(!powerGrid.empty() ? powerGrid.top() : -1);
        }
      } else if (op == 2) {
        vertices[x].offline = true;
      }
    }
    return ans;
  }
};

class Solution {
 public:
  int minMoves(vector<string>& classroom, int energy) {
    queue<tuple<int, int, int, int>> q;
    int n = classroom.size(), m = classroom[0].size();
    vector<vector<int>> litterId(n, vector<int>(m, -1));
    int L = 0;
    int si = -1, sj = -1;
    // pushing the start point in queue
    for (int i = 0; i < n; i++) {
      for (int j = 0; j < m; j++) {
        if (classroom[i][j] == 'L') {
          litterId[i][j] = L;
          L++;
        }

        if (classroom[i][j] == 'S') {
          si = i;
          sj = j;
        }
      }
    }

    // if nothing to collect return 0 moves
    if (L == 0) return 0;
    int fullMask = (1 << L) - 1;
    vector<vector<vector<vector<bool>>>> vis(
        n,
        vector<vector<vector<bool>>>(
            m, vector<vector<bool>>(energy + 1, vector<bool>(1 << L, false))));
    q.push({si, sj, energy, 0});
    vis[si][sj][energy][0] = true;
    vector<vector<int>> dir = {{1, 0}, {-1, 0}, {0, 1}, {0, -1}};

    // processing the bfs
    int level = 0;

    while (!q.empty()) {
      int size = q.size();

      while (size--) {
        auto [i, j, e, mask] = q.front();

        // cout << "i:- " << i << " j:- " << j << " e:- " << e << " l:- "
        //      << l << endl;

        q.pop();

        for (auto& d : dir) {
          int ni = i + d[0];
          int nj = j + d[1];
          int ne = e - 1;
          int nm = mask;
          if (ni >= n || ni < 0 || nj >= m || nj < 0) continue;

          if (classroom[ni][nj] == 'X') continue;
          if (ne < 0) continue;
          if (classroom[ni][nj] == 'R') ne = energy;

          if (classroom[ni][nj] == 'L') {
            int id = litterId[ni][nj];
            nm = mask | (1 << id);
          }
          if (nm == fullMask) {
            return level + 1;
          }

          // cout << "ni:- " << ni << " nj:- " << nj << " e:- " << e
          //      << " l:- " << nm << endl;

          if (!vis[ni][nj][ne][nm]) {
            vis[ni][nj][ne][nm] = true;
            q.push({ni, nj, ne, nm});
          }
        }
      }

      level++;
    }

    return -1;
  }
};

class Solution {
 public:
  vector<vector<int>> minAbsDiff(vector<vector<int>>& grid, int k) {
    int n = grid.size();
    int m = grid[0].size();
    vector<vector<int>> ans(n - k + 1, vector<int>(m - k + 1));
    for (int i = 0; i <= n - k; i++) {
      for (int j = 0; j <= m - k; j++) {
        set<int> s;
        for (int id = i; id < i + k; id++) {
          for (int jd = j; jd < j + k; jd++) {
            s.insert(grid[id][jd]);
          }
        }
        if (s.size() <= 1) {
          ans[i][j] = 0;
          continue;
        }
        int mine = INT_MAX;
        auto pre = s.begin();
        auto curr = next(pre);
        while (curr != s.end()) {
          mine = min(mine, abs(*curr - *pre));
          pre = curr;
          curr++;
        }
        ans[i][j] = mine;
      }
    }
    return ans;
  }
};

class Solution {
 public:
  vector<vector<pair<int, int>>> G;

  int dijkstra(int n) {
    vector<bool> vis(n, false);
    vector<int> dist(n, 1e9);

    priority_queue<pair<int, int>> Q;
    Q.push({0, 0});
    dist[0] = 0;
    while (!Q.empty()) {
      int u = Q.top().second;
      Q.pop();
      if (vis[u]) continue;
      vis[u] = true;
      for (auto [v, w] : G[u]) {
        if (dist[u] + w < dist[v]) {
          dist[v] = dist[u] + w;
          Q.push({-dist[v], v});
        }
      }
    }
    if (dist[n - 1] == 1e9) return -1;
    return dist[n - 1];
  }

  int minCost(int n, vector<vector<int>>& edges) {
    G.resize(n);
    for (auto edge : edges) {
      int u = edge[0];
      int v = edge[1];
      int w = edge[2];
      G[u].push_back({v, w});
      G[v].push_back({u, 2 * w});
    }
    return dijkstra(n);
  }
};

class Solution {
 public:
  int minCost(vector<vector<int>>& grid, int k) {
    int m = grid.size();
    int n = grid[0].size();

    // initialize adjacency list
    vector<vector<pair<int, int>>> adj(10001);
    for (int i = 0; i < m; i++) {
      for (int j = 0; j < n; j++) {
        adj[grid[i][j]].push_back({i, j});
      }
    }

    // initialize cost matrix (k,row,col)

    vector<vector<vector<int>>> cost(
        k + 1, vector<vector<int>>(m, vector<int>(n, INT_MAX)));
    priority_queue<tuple<int, int, int, int>, vector<tuple<int, int, int, int>>,
                   greater<tuple<int, int, int, int>>>
        pq;

    // initialize the maxi array

    vector<int> maxi(k + 1, -1);

    // put the intial values in the pq and mark cost to be 0

    pq.push({0, 0, 0, 0});
    cost[0][0][0] = 0;
    while (!pq.empty()) {
      auto [c, row, col, c_k] = pq.top();
      pq.pop();
      if (c > cost[c_k][row][col]) continue;

      // if reached last cell return cost
      if (row == m - 1 && col == n - 1) return c;

      // Normal moves

      int dx[] = {0, 1};
      int dy[] = {1, 0};
      for (int i = 0; i < 2; i++) {
        int nrow = row + dx[i];
        int ncol = col + dy[i];
        if (nrow >= 0 && ncol >= 0 && nrow < m && ncol < n) {
          int ncost = c + grid[nrow][ncol];
          if (ncost < cost[c_k][nrow][ncol]) {
            cost[c_k][nrow][ncol] = ncost;
            pq.push({ncost, nrow, ncol, c_k});
          }
        }
      }

      // Teleportation moves

      if (c_k < k) {
        int val = grid[row][col];
        int n_k = c_k + 1;

        // loop from maximum value to current val of grid

        for (int i = maxi[n_k] + 1; i <= val; i++) {
          for (auto it : adj[i]) {
            int x = it.first;
            int y = it.second;
            if (c < cost[n_k][x][y]) {
              cost[n_k][x][y] = c;
              pq.push({c, x, y, n_k});
            }
          }
        }

        // update the maximum value reached to current value of grid

        maxi[n_k] = max(maxi[n_k], val);
      }
    }
    return 0;
  }
};

class DSU {
 public:
  vector<int> parent, rankv;
  int components;

  DSU(int n) {
    parent.resize(n);
    rankv.assign(n, 0);
    iota(parent.begin(), parent.end(), 0);
    components = n;
  }

  int find(int x) {
    if (parent[x] != x) parent[x] = find(parent[x]);
    return parent[x];
  }

  bool unite(int a, int b) {
    a = find(a);
    b = find(b);

    if (a == b) return false;

    if (rankv[a] < rankv[b]) swap(a, b);
    parent[b] = a;
    if (rankv[a] == rankv[b]) rankv[a]++;

    components--;
    return true;
  }
};

class Solution {
 public:
  bool canAchieve(int n, vector<vector<int>> &edges, int k, int x) {
    DSU dsu(n);

    // 1. Mandatory edges must be included
    for (auto &e : edges) {
      int u = e[0], v = e[1], s = e[2], must = e[3];

      if (must == 1) {
        if (s < x) return false;             // mandatory edge too weak
        if (!dsu.unite(u, v)) return false;  // mandatory cycle
      }
    }

    // 2. Use all free optional edges
    for (auto &e : edges) {
      int u = e[0], v = e[1], s = e[2], must = e[3];

      if (must == 0 && s >= x) {
        dsu.unite(u, v);
      }
    }

    // 3. Use upgradeable optional edges if needed
    int usedUpgrades = 0;

    for (auto &e : edges) {
      int u = e[0], v = e[1], s = e[2], must = e[3];

      if (must == 0 && s < x && 2 * s >= x) {
        if (dsu.unite(u, v)) {
          usedUpgrades++;
          if (usedUpgrades > k) return false;
        }
      }
    }

    return dsu.components == 1;
  }

  int maxStability(int n, vector<vector<int>> &edges, int k) {
    // Early check: mandatory edges alone must not form a cycle
    {
      DSU dsu(n);
      for (auto &e : edges) {
        if (e[3] == 1) {
          if (!dsu.unite(e[0], e[1])) return -1;
        }
      }
    }

    int low = 1, high = 200000, ans = -1;

    while (low <= high) {
      int mid = low + (high - low) / 2;

      if (canAchieve(n, edges, k, mid)) {
        ans = mid;
        low = mid + 1;
      } else {
        high = mid - 1;
      }
    }

    return ans;
  }
};

class Solution {
