class Solution {
 public:
  int xorAfterQueries(vector<int>& nums, vector<vector<int>>& queries) {
    const int mod = 1e9 + 7;
    for (auto q : queries) {
      int l = q[0];
      int v = q[3];
      int r = q[1];
      int k = q[2];
      if (k == 0) continue;
      for (int i = l; i <= r; i += k) {
        nums[i] = (1LL * nums[i] * v) % mod;
      }
    }
    int ans = 0;
    for (int i = 0; i < nums.size(); i++) {
      ans ^= nums[i];
    }
    return ans;
  }
};

class Solution {
 public:
  int M = 1e9 + 7;
  long long power(long long a, long long b) {
    if (b == 0) return 1;
    long long half = power(a, b / 2);
    long long result = (half * half) % M;
    if (b % 2 == 1) {
      result = (result * a) % M;
    }
    return result;
  }
  int xorAfterQueries(vector<int>& nums, vector<vector<int>>& queries) {
    int n = nums.size();
    int blockSize = ceil(sqrt(n));
    unordered_map<int, vector<vector<int>>> smallKMap;
    for (auto& query : queries) {
      int L = query[0];
      int R = query[1];
      int K = query[2];
      int V = query[3];

      if (K >= blockSize) {
        for (int i = L; i <= R; i += K) {
          nums[i] = (1LL * nums[i] * V) % M;
        }
      } else {
        smallKMap[K].push_back(query);
      }
    }
    for (auto& [K, allQueries] : smallKMap) {
      vector<long long> diff(n, 1);
      for (auto& query : allQueries) {
        int L = query[0];
        int R = query[1];
        int V = query[3];
        diff[L] = (diff[L] * V) % M;
        int steps = (R - L) / K;
        int next = L + (steps + 1) * K;
        if (next < n) diff[next] = (diff[next] * power(V, M - 2)) % M;
      }
      for (int i = 0; i < n; i++) {
        if (i - K >= 0) diff[i] = (diff[i] * diff[i - K]) % M;
      }
      for (int i = 0; i < n; i++) {
        nums[i] = (1LL * nums[i] * diff[i]) % M;
      }
    }
    int result = 0;
    for (int& num : nums) {
      result = (result ^ num);
    }

    return result;
  }
};

class Solution {
 public:
  vector<int> maxValue(vector<int>& nums) {
    int n = nums.size();

    vector<int> pre(n), suf(n), res(n);

    // prefix max
    pre[0] = nums[0];
    for (int i = 1; i < n; i++) {
      pre[i] = max(pre[i - 1], nums[i]);
    }

    // suffix min
    suf[n - 1] = nums[n - 1];
    for (int i = n - 2; i >= 0; i--) {
      suf[i] = min(suf[i + 1], nums[i]);
    }

    res[n - 1] = pre[n - 1];

    // build answer
    for (int i = n - 2; i >= 0; i--) {
      // merge segment
      if (pre[i] > suf[i + 1]) {
        res[i] = res[i + 1];
      }

      // new segment
      else {
        res[i] = pre[i];
      }
    }

    return res;
  }
};

class Solution {
 public:
  int minOperations(string s, int k) {
    int zero = 0;
    int len = s.length();

    for (int i = 0; i < len; i++) zero += ~s[i] & 1;

    if (!zero) return 0;

    if (len == k) return ((zero == len) << 1) - 1;

    int base = len - k;

    int odd = max((zero + k - 1) / k, (len - zero + base - 1) / base);

    odd += ~odd & 1;

    int even = max((zero + k - 1) / k, (zero + base - 1) / base);

    even += even & 1;

    int res = INT_MAX;

    if ((k & 1) == (zero & 1)) res = min(res, odd);

    if (~zero & 1) res = min(res, even);

    return res == INT_MAX ? -1 : res;
  }
};

class Solution {
  const int NEG = -1e9;

  int rec(int i, int j, vector<vector<int>>& grid, int k,
          vector<vector<vector<int>>>& dp) {
    int n = grid.size();
    int m = grid[0].size();

    if (i >= n || j >= m) return NEG;

    int cost = (grid[i][j] == 0 ? 0 : 1);

    if (k < cost) return NEG;

    if (i == n - 1 && j == m - 1) {
      return grid[i][j];
    }

    if (dp[i][j][k] != -1) {
      return dp[i][j][k];
    }

    int r = rec(i, j + 1, grid, k - cost, dp);
    int d = rec(i + 1, j, grid, k - cost, dp);

    int best = max(r, d);

    if (best == NEG) {
      return dp[i][j][k] = NEG;
    }

    return dp[i][j][k] = grid[i][j] + best;
  }

 public:
  int maxPathScore(vector<vector<int>>& grid, int k) {
    int n = grid.size();
    int m = grid[0].size();
    vector<vector<vector<int>>> dp(
        n, vector<vector<int>>(m, vector<int>(k + 1, -1)));
    int ans = rec(0, 0, grid, k, dp);
    return (ans < 0) ? -1 : ans;
  }
};

